window.UC_FLOW_CATALOG = [{"id":"sip-basic","title":"Basic SIP dialog","why":"Every later hop is a guess until this ladder is right: offer, answer, ACK, media, BYE.","cite":"RFC 3261 and RFC 3264","layout":"ladder","actors":["Alice UAC","Bob UAS"],"chart":"sip","icon":"sip","keys":[["5060","SIP UDP and TCP"],["5061","SIP over TLS"],["Call-ID","Same dialog on a proxy"],["CSeq","Rises inside the dialog"]],"header":"invite","audio":true,"steps":[{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"Alice sends INVITE with a new Call-ID, a From tag, and an SDP offer. The branch id starts this transaction."},{"f":1,"t":0,"label":"100 Trying","kind":"prov","cap":"100 Trying is hop by hop. It only means the next hop is working on the INVITE. It does not mean Bob is ringing."},{"f":1,"t":0,"label":"180 Ringing","kind":"prov","cap":"180 Ringing is provisional. The dialog is not confirmed. A phone may start local ringback from this response."},{"f":1,"t":0,"label":"200 OK","kind":"ok","cap":"Bob accepts. The 200 carries the SDP answer and Bob's To tag. Offer and answer are now complete."},{"f":0,"t":1,"label":"ACK","kind":"req","cap":"Alice sends ACK. For a 2xx, that ACK is end to end: it is not retransmitted as its own transaction the way a non-2xx ACK is."},{"f":0,"t":1,"label":"RTP","kind":"media","cap":"Media follows the SDP addresses, not the SIP path. One-way audio is an RTP problem unless the 200 never completed."},{"f":0,"t":1,"label":"BYE","kind":"bye","cap":"Either party sends BYE inside the dialog. The Call-ID and tags stay the same."},{"f":1,"t":0,"label":"200 OK","kind":"ok","cap":"The BYE is answered with 200 OK. The dialog is over. A later packet with this Call-ID is a new problem, not this call."}]},{"id":"sip-proxy","title":"INVITE through a proxy","why":"A proxy is in the signaling path only. 100 Trying stops retransmissions; it is not forwarded as a sign that the far end is ringing.","cite":"RFC 3261 sections 16 and 17","layout":"ladder","actors":["Alice","Proxy","Bob"],"chart":"sip","icon":"sip","keys":[["5060","SIP UDP and TCP"],["5061","SIP over TLS"],["Call-ID","Same dialog on a proxy"],["CSeq","Rises inside the dialog"]],"header":"invite","audio":true,"steps":[{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"Alice sends INVITE to the outbound proxy. Via and the branch identify this hop."},{"f":1,"t":0,"label":"100 Trying","kind":"prov","cap":"The proxy sends 100 Trying to Alice. That response is hop by hop and is not relayed from Bob."},{"f":1,"t":2,"label":"INVITE","kind":"req","cap":"The proxy forwards the INVITE. A pure proxy keeps the Call-ID. It adds its own Via."},{"f":2,"t":1,"label":"180 Ringing","kind":"prov","cap":"Bob sends 180. The proxy will forward this provisional response back along the Via stack."},{"f":1,"t":0,"label":"180 Ringing","kind":"prov","cap":"Alice receives 180. Local ringback may start. Early media has not been negotiated unless SDP already arrived."},{"f":2,"t":1,"label":"200 OK","kind":"ok","cap":"Bob sends 200 OK with the answer SDP and a To tag. The dialog exists."},{"f":1,"t":0,"label":"200 OK","kind":"ok","cap":"The proxy forwards the 200. It does not generate the ACK for a 2xx."},{"f":0,"t":1,"label":"ACK","kind":"req","cap":"Alice generates the ACK. If the proxy inserted Record-Route, the route set sends this ACK via the proxy."},{"f":1,"t":2,"label":"ACK","kind":"req","cap":"The proxy forwards the ACK. The CSeq number matches the INVITE. The method is ACK."},{"f":0,"t":2,"label":"RTP","kind":"media","cap":"RTP does not have to hairpin through the proxy. If it does, something else is anchoring media."}]},{"id":"sip-183","title":"Early media with 183","why":"183 Session Progress can carry the SDP answer before the call is answered. That is how in-band announcements and network ringback are played. Silence here is an early-media fault, not a missing 180.","cite":"RFC 3261 and RFC 3960","layout":"ladder","actors":["Alice","Bob"],"chart":"sip","icon":"media","keys":[["RTP","Even UDP port, dynamic"],["RTCP","Usually RTP port + 1"],["16384\u201332767","Common Cisco range"],["SDP c= / m=","Where media is sent"]],"header":"sdp","audio":true,"steps":[{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"The INVITE carries the offer. Early media needs an answer before 200 OK."},{"f":1,"t":0,"label":"100 Trying","kind":"prov","cap":"100 Trying still means only that the request is being handled."},{"f":1,"t":0,"label":"183 + SDP","kind":"prov","cap":"183 Session Progress carries the answer SDP. Early RTP may start now. A 180 without SDP does not do this."},{"f":1,"t":0,"label":"early RTP","kind":"media","cap":"One-way media before answer: ringback, an intercept message, or a carrier tone. Two-way speech is not established yet."},{"f":1,"t":0,"label":"200 OK","kind":"ok","cap":"Answer. If the 183 already completed offer/answer, the 200 often repeats that SDP rather than opening a new negotiation."},{"f":0,"t":1,"label":"ACK","kind":"req","cap":"ACK confirms the dialog. Media continues on the negotiated ports."}]},{"id":"sip-prack","title":"Reliable provisional response (PRACK)","why":"If the far end requires 100rel, a 183 that carries SDP is not final until PRACK. Lost early media is often a missing PRACK, not a codec bug.","cite":"RFC 3262","layout":"ladder","actors":["Alice","Bob"],"chart":"sip","icon":"sip","keys":[["5060","SIP UDP and TCP"],["5061","SIP over TLS"],["Call-ID","Same dialog on a proxy"],["CSeq","Rises inside the dialog"]],"header":"invite","audio":true,"steps":[{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"Alice offers 100rel in Supported, or the network Requires it."},{"f":1,"t":0,"label":"183 RSeq","kind":"prov","cap":"The 183 includes Require: 100rel and an RSeq number. The UAS will retransmit this 183 until PRACK arrives."},{"f":0,"t":1,"label":"PRACK","kind":"req","cap":"PRACK names that RSeq in RAck. This is its own transaction."},{"f":1,"t":0,"label":"200 PRACK","kind":"ok","cap":"200 OK answers the PRACK, not the INVITE. The INVITE is still outstanding."},{"f":1,"t":0,"label":"200 INVITE","kind":"ok","cap":"Now the UAS accepts the INVITE."},{"f":0,"t":1,"label":"ACK","kind":"req","cap":"ACK completes the INVITE dialog. Do not confuse it with the PRACK."}]},{"id":"sip-hold","title":"Hold and resume with re-INVITE","why":"Hold is a change to the existing dialog, not a second call. RFC 3264 uses a=sendonly and a=recvonly. a=inactive means neither side sends.","cite":"RFC 3264","layout":"ladder","actors":["Holder","Held party"],"chart":"codec","icon":"media","keys":[["a=sendonly","Holder"],["a=recvonly","Held party"],["re-INVITE","Same Call-ID"],["CSeq + 1","New transaction"]],"header":"hold","audio":true,"steps":[{"f":0,"t":1,"label":"re-INVITE","kind":"req","cap":"Same Call-ID, new CSeq, SDP with a=sendonly. This is the holder offering to stop sending media."},{"f":1,"t":0,"label":"200 OK","kind":"ok","cap":"The held party answers with a=recvonly. If it answers sendrecv, the hold did not take."},{"f":0,"t":1,"label":"ACK","kind":"req","cap":"ACK locks the held session."},{"f":0,"t":1,"label":"one-way RTP","kind":"media","cap":"Media, if any, flows toward the holder. Music on hold is a separate source the holder may play."},{"f":0,"t":1,"label":"re-INVITE","kind":"req","cap":"Resume is another re-INVITE with a=sendrecv."},{"f":1,"t":0,"label":"200 OK","kind":"ok","cap":"The answer returns to sendrecv."},{"f":0,"t":1,"label":"ACK","kind":"req","cap":"ACK completes resume. A failed resume leaves the dialog up and the media on hold."}]},{"id":"sip-refer","title":"Blind transfer with REFER","why":"REFER asks the other user agent to start a new request. 202 means the REFER was accepted, not that the transfer target answered.","cite":"RFC 3515","layout":"ladder","actors":["Alice","Bob","Carol"],"chart":"sip","icon":"sip","keys":[["202","REFER accepted"],["NOTIFY","sipfrag result"],["Refer-To","The target"],["New Call-ID","Bob to Carol"]],"header":"invite","audio":false,"steps":[{"f":0,"t":1,"label":"REFER","kind":"req","cap":"Alice sends REFER to Bob with Refer-To set to Carol. This rides the existing dialog."},{"f":1,"t":0,"label":"202 Accepted","kind":"ok","cap":"202 accepts the REFER request. Carol has not been contacted yet."},{"f":1,"t":0,"label":"NOTIFY 100","kind":"prov","cap":"Bob opens the subscription and sends NOTIFY with a sipfrag, often SIP/2.0 100 Trying."},{"f":1,"t":2,"label":"INVITE","kind":"req","cap":"Bob places a new INVITE to Carol. That dialog has its own Call-ID."},{"f":2,"t":1,"label":"200 OK","kind":"ok","cap":"Carol answers Bob."},{"f":1,"t":2,"label":"ACK","kind":"req","cap":"Bob completes the new dialog."},{"f":1,"t":0,"label":"NOTIFY 200","kind":"ok","cap":"NOTIFY tells Alice the referred request got a 200. This is the success signal."},{"f":0,"t":1,"label":"BYE","kind":"bye","cap":"Alice drops the original dialog. Bob and Carol stay up on the new one."}]},{"id":"sip-attended","title":"Attended transfer with Replaces","why":"Attended transfer uses a consultation call first. Replaces names that dialog so Carol's phone swaps the consult for the original party.","cite":"RFC 3515 and RFC 3891","layout":"ladder","actors":["Alice","Bob","Carol"],"chart":"none","icon":"sip","keys":[["Replaces","Target dialog"],["Consult","Second Call-ID"],["202","Not the answer"],["NOTIFY","Final status"]],"header":"invite","audio":false,"steps":[{"f":0,"t":2,"label":"INVITE","kind":"req","cap":"Alice consults Carol on a second dialog and waits until Carol answers."},{"f":2,"t":0,"label":"200 OK","kind":"ok","cap":"The consultation is up. Alice now has two dialogs."},{"f":0,"t":1,"label":"REFER","kind":"req","cap":"Alice sends REFER to Bob. Refer-To includes a Replaces parameter for the Alice\u2013Carol dialog."},{"f":1,"t":0,"label":"202 Accepted","kind":"ok","cap":"Bob accepts the request to replace."},{"f":1,"t":2,"label":"INVITE","kind":"req","cap":"Bob invites Carol with Replaces. Carol matches the existing dialog."},{"f":2,"t":1,"label":"200 OK","kind":"ok","cap":"Carol accepts Bob and drops the consultation with Alice."},{"f":1,"t":0,"label":"NOTIFY 200","kind":"ok","cap":"Alice sees the referred call succeed, then BYE on both of her dialogs."}]},{"id":"sip-cancel","title":"CANCEL before answer","why":"CANCEL stops a ringing INVITE. It uses the same branch as that INVITE. The INVITE itself ends with 487, and that 487 still needs an ACK.","cite":"RFC 3261 section 9","layout":"ladder","actors":["Alice","Bob"],"chart":"sip","icon":"sip","keys":[["5060","SIP UDP and TCP"],["5061","SIP over TLS"],["Call-ID","Same dialog on a proxy"],["CSeq","Rises inside the dialog"]],"header":"invite","audio":false,"steps":[{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"The INVITE is outstanding. CANCEL is legal only before a final response."},{"f":1,"t":0,"label":"180 Ringing","kind":"prov","cap":"Bob is alerting. No dialog is confirmed yet."},{"f":0,"t":1,"label":"CANCEL","kind":"bye","cap":"CANCEL carries the same branch as the INVITE. It is its own request."},{"f":1,"t":0,"label":"200 CANCEL","kind":"ok","cap":"200 answers the CANCEL. The INVITE is not finished by this 200."},{"f":1,"t":0,"label":"487","kind":"err","cap":"487 Request Terminated answers the INVITE."},{"f":0,"t":1,"label":"ACK","kind":"req","cap":"ACK for a non-2xx is hop by hop and belongs to that INVITE transaction. Skipping it leaves retransmissions running."}]},{"id":"sip-407","title":"Proxy authentication","why":"407 is the proxy challenging the request. 401 is the UAS. The ACK for that non-2xx, then a new INVITE with the authorization header, is the whole story.","cite":"RFC 3261 sections 22 and 17","layout":"ladder","actors":["Alice","Proxy"],"chart":"sip","icon":"cert","keys":[["407","Proxy challenge"],["401","UAS challenge"],["New branch","New INVITE"],["CSeq + 1","Not a retransmission"]],"header":"invite","audio":false,"steps":[{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"First INVITE has no credentials."},{"f":1,"t":0,"label":"407","kind":"err","cap":"407 Proxy Authentication Required carries Proxy-Authenticate. A 401 would carry WWW-Authenticate instead."},{"f":0,"t":1,"label":"ACK","kind":"req","cap":"ACK the 407. It is a non-2xx final response."},{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"A new INVITE, new branch, CSeq incremented, with Proxy-Authorization."},{"f":1,"t":0,"label":"180 Ringing","kind":"prov","cap":"The challenge succeeded. The call proceeds."}]},{"id":"sip-options","title":"OPTIONS keepalive","why":"OPTIONS asks whether the far end can take a call. A trunk that answers OPTIONS and drops INVITE is a policy failure, not a routing failure.","cite":"RFC 3261 section 11","layout":"ladder","actors":["SBC","Peer"],"chart":"none","icon":"sip","keys":[["OPTIONS","Out of dialog"],["200","Reachable"],["INVITE","Still separate"],["ACL","Can still drop RTP"]],"header":"invite","audio":true,"steps":[{"f":0,"t":1,"label":"OPTIONS","kind":"req","cap":"The SBC sends OPTIONS on an interval. No dialog is created."},{"f":1,"t":0,"label":"200 OK","kind":"ok","cap":"200 means the peer is willing to receive requests. It says nothing about media ACLs."},{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"A real call is a separate transaction. Do not treat a green OPTIONS counter as proof of audio."}]},{"id":"sip-delayed","title":"Delayed offer","why":"Delayed offer puts no SDP in the INVITE. The offer arrives in the 200, and the answer comes back in the ACK. Early offer is the opposite.","cite":"RFC 3261 and RFC 3264","layout":"ladder","actors":["UAC","UAS"],"chart":"codec","icon":"media","keys":[["No SDP","Delayed offer"],["Offer in 200","UAS offers"],["Answer in ACK","UAC answers"],["Early offer","SDP already in INVITE"]],"header":"invite","audio":true,"steps":[{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"No SDP body. The UAC has not offered a codec yet."},{"f":1,"t":0,"label":"180 Ringing","kind":"prov","cap":"Alerting can still happen. There is no media to play until offer/answer completes."},{"f":1,"t":0,"label":"200 + SDP","kind":"ok","cap":"The UAS offers SDP in the 200 OK."},{"f":0,"t":1,"label":"ACK + SDP","kind":"req","cap":"The UAC answers in the ACK. If this ACK is lost, the UAS has no answer and media does not start."},{"f":0,"t":1,"label":"RTP","kind":"media","cap":"RTP starts only after that answer. A capture that shows 200 OK and no ACK is this fault."}]},{"id":"sip-dtmf","title":"RFC 2833 telephone events","why":"Named events in RTP are the usual DTMF path. SIP INFO and KPML are different tools. An IVR that is deaf after G.729 often never received events, because the transcoder or the SBC dropped them.","cite":"RFC 4733 (updates RFC 2833)","layout":"ladder","actors":["Phone","IVR"],"chart":"codec","icon":"media","keys":[["PT 101","Common telephone-event"],["End bit","Digit finished"],["INFO","A different method"],["KPML","SUBSCRIBE for digits"]],"header":"invite","audio":true,"steps":[{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"The offer includes telephone-event, often payload 101, for the codec that will carry the audio."},{"f":1,"t":0,"label":"200 OK","kind":"ok","cap":"The answer agrees to telephone-event. If it does not, digits will not arrive as events."},{"f":0,"t":1,"label":"RTP audio","kind":"media","cap":"Speech uses the voice payload."},{"f":0,"t":1,"label":"RTP event","kind":"media","cap":"The digit is a named telephony event in the same RTP stream, with a marker and an end bit. It is not a tone in the audio unless the SBC converts it."}]},{"id":"sip-486","title":"Busy and 486","why":"486 Busy Here is a final response from the UAS. The UAC ACKs it and does not send BYE, because no dialog was confirmed.","cite":"RFC 3261","layout":"ladder","actors":["Alice","Bob"],"chart":"sip","icon":"phone","keys":[["486","Busy Here"],["600","Busy Everywhere"],["480","Temporarily unavailable"],["ACK","Required for non-2xx"]],"header":"invite","audio":true,"steps":[{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"Alice calls Bob."},{"f":1,"t":0,"label":"486 Busy","kind":"err","cap":"Bob's UAS is busy. This is final. It is not 180 and it is not CANCEL."},{"f":0,"t":1,"label":"ACK","kind":"req","cap":"ACK the 486. Stop. There is no BYE."}]},{"id":"sip-503","title":"503 and retry storms","why":"503 means this server cannot take the request now. Retry-After, if present, is the timer. A client that immediately retries every 503 will melt the peer.","cite":"RFC 3261","layout":"ladder","actors":["UAC","Server"],"chart":"sip","icon":"sip","keys":[["503","This server, now"],["Retry-After","Wait"],["500","Server internal error"],["Failover","Next peer, not a tight loop"]],"header":"invite","audio":false,"steps":[{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"A call arrives while the server is overloaded or in maintenance."},{"f":1,"t":0,"label":"503","kind":"err","cap":"503 Service Unavailable. Read Retry-After before you try again."},{"f":0,"t":1,"label":"ACK","kind":"req","cap":"ACK the 503."},{"f":0,"t":1,"label":"INVITE","kind":"err","cap":"An immediate new INVITE is how a 503 becomes a retry storm. Back off, or fail over to the next peer in the route."}]},{"id":"stir-shaken","title":"STIR/SHAKEN Identity","why":"The Identity header signs the calling number. If an SBC strips PAI or From and does not rebuild the identity, verification fails downstream and the call looks spoofed.","cite":"RFC 8224","layout":"ladder","actors":["Originating SP","Transit","Terminating SP"],"chart":"none","icon":"cert","keys":[["Identity","Signed token"],["PAI","Do not strip blindly"],["Attestation","A, B, or C"],["Date","Clock skew fails verification"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"INVITE + Identity","kind":"req","cap":"The originating provider adds an Identity header over the attested calling number and a date."},{"f":1,"t":2,"label":"INVITE","kind":"req","cap":"Transit must pass the Identity header and the signed calling information. A SIP profile that deletes PAI can break the attestation."},{"f":2,"t":1,"label":"verify","kind":"note","cap":"The terminating provider checks the signature against the provider certificate. A fail is a signing or header-stripping problem, not a dial-plan problem."},{"f":2,"t":1,"label":"180 / 200","kind":"ok","cap":"The call can still complete while verification fails. The symptom is often a label or a dropped call only where policy requires a pass."}]},{"id":"sip-tls","title":"SIP over TLS","why":"TLS protects signaling, not RTP. SRTP is a separate negotiation. A trunk can be TLS-up and still play unencrypted audio, or fail SRTP and go silent.","cite":"RFC 3261 and RFC 3711","layout":"ladder","actors":["Client","Server"],"chart":"sip","icon":"cert","keys":[["5061","SIP TLS"],["mTLS","Both certificates"],["SRTP","Separate from TLS"],["Chain","Intermediate must be sent"]],"header":"invite","audio":true,"steps":[{"f":0,"t":1,"label":"TCP 5061","kind":"req","cap":"The client opens TLS. 5061 is the registered SIP TLS port. Webex Calling and Teams use their own documented ports on top of this idea."},{"f":0,"t":1,"label":"Certificate","kind":"note","cap":"Each side checks the name in the certificate against the name it dialed. An incomplete chain fails before any INVITE."},{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"The INVITE rides inside TLS. A capture on the wire shows records, not cleartext SIP, unless you have the keys."},{"f":0,"t":1,"label":"SRTP","kind":"media","cap":"Media encryption is negotiated in SDP (RTP/SAVP or a UDP/TLS/RTP/SAVPF profile). It is not implied by SIP TLS."}]},{"id":"codec-neg","title":"Offer and answer codec choice","why":"The answerer picks one payload from the offer for each stream it accepts. Sending a codec the answer did not list is how you get silence with a perfect 200 OK.","cite":"RFC 3264","layout":"ladder","actors":["Offerer","Answerer"],"chart":"codec","icon":"media","keys":[["m= audio","Port and payloads"],["port 0","Stream rejected"],["rtpmap","Name the payload"],["fmtp","Required parameters"]],"header":null,"audio":true,"steps":[{"f":0,"t":1,"label":"offer","kind":"req","cap":"The offer lists payloads in preference order, with rtpmap and fmtp."},{"f":1,"t":0,"label":"answer","kind":"ok","cap":"The answer keeps one payload for the stream, or rejects the stream with port 0."},{"f":0,"t":1,"label":"RTP","kind":"media","cap":"Both sides send the answered payload. A ptime mismatch is legal within limits; a payload mismatch is not."}]},{"id":"rtp-plane","title":"RTP and RTCP beside SIP","why":"Signaling can be perfect while RTP is blackholed. RTP is its own UDP flow. RTCP on the next port tells you whether the other side is receiving.","cite":"RFC 3550","layout":"ladder","actors":["Sender","Receiver"],"chart":"mos","icon":"media","keys":[["RTP","Even UDP port, dynamic"],["RTCP","Usually RTP port + 1"],["16384\u201332767","Common Cisco range"],["SDP c= / m=","Where media is sent"]],"header":"sdp","audio":true,"steps":[{"f":0,"t":1,"label":"SDP","kind":"req","cap":"c= is the address. m= is the port and payload. That pair is the media target."},{"f":0,"t":1,"label":"RTP","kind":"media","cap":"Even UDP port is the usual RTP port. Sequence numbers and timestamps move only when packets are sent."},{"f":1,"t":0,"label":"RTCP","kind":"media","cap":"RTCP receiver reports show loss and jitter as the receiver saw them. No RTCP often means the return path is filtered."},{"f":0,"t":1,"label":"BYE","kind":"bye","cap":"SIP BYE does not itself stop a stream that a device failed to close. Check the counters after the BYE."}]},{"id":"srtp-sdes","title":"SRTP with SDES","why":"SRTP without a matching crypto suite is silence, not garbled audio. Both sides must agree the profile and the key in SDP.","cite":"RFC 3711 and RFC 4568","layout":"ladder","actors":["Alice","Bob"],"chart":"mos","icon":"cert","keys":[["RTP/SAVP","Secure AVP"],["a=crypto","SDES key"],["Suite","Must overlap"],["TLS","Does not encrypt RTP"]],"header":null,"audio":true,"steps":[{"f":0,"t":1,"label":"RTP/SAVP","kind":"req","cap":"The offer uses a secure profile and lists a=crypto with a suite and a key."},{"f":1,"t":0,"label":"answer","kind":"ok","cap":"The answer selects one suite. If the suites do not overlap, the call may signal and then carry no decodeable media."},{"f":0,"t":1,"label":"SRTP","kind":"media","cap":"The UDP payload is encrypted. A capture still shows packets. A phone shows them as received and drops them if the key is wrong."}]},{"id":"nat-media","title":"NAT and the media latch","why":"The address in SDP is useless if it is a private address the far end cannot route. Symmetric latching or ICE has to learn the public mapped port.","cite":"RFC 6314 behavior, SDP c=","layout":"ladder","actors":["Phone","NAT","SBC"],"chart":"codec","icon":"route","keys":[["c=","Declared address"],["Latch","Learned address"],["SIP ALG","Turn it off"],["ICE","Better when both sides support it"]],"header":null,"audio":true,"steps":[{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"SDP c= may say a private address. That address is not on the public side of the NAT."},{"f":1,"t":2,"label":"INVITE","kind":"req","cap":"If nothing rewrites c=, the SBC sends RTP to a private address and the packets die."},{"f":2,"t":1,"label":"RTP","kind":"media","cap":"The SBC can latch onto the source address of RTP that actually arrives, when latching is enabled."},{"f":0,"t":2,"label":"RTP","kind":"media","cap":"After the latch, media flows to the mapped port. A SIP ALG that rewrites SDP badly fights the SBC and should be off."}]},{"id":"ice","title":"ICE, STUN, and TURN","why":"ICE gathers candidates, checks them in pairs, and nominates one pair. TURN is a relay for the pairs that cannot punch through. It is not the first choice.","cite":"RFC 8445, RFC 8489, RFC 8656","layout":"ladder","actors":["Agent","STUN/TURN","Peer"],"chart":"none","icon":"media","keys":[["Host","Local address"],["srflx","STUN mapped"],["relay","TURN"],["Nominated","The pair in use"]],"header":null,"audio":true,"steps":[{"f":0,"t":1,"label":"gather","kind":"note","cap":"The browser gathers host candidates and asks STUN for a server-reflexive address. TURN allocates a relay if configured."},{"f":0,"t":2,"label":"checks","kind":"media","cap":"Connectivity checks run on candidate pairs. The nominated pair is the one media will use."},{"f":0,"t":1,"label":"TURN relay","kind":"media","cap":"If no direct pair works, media hairpins through TURN. Capacity on that relay is a real limit for home agents."},{"f":0,"t":2,"label":"SRTP","kind":"media","cap":"The selected pair is one address family. An IPv4-only candidate does not carry an IPv6 stream."}]},{"id":"webrtc","title":"WebRTC agent desktop","why":"A browser agent does not send RTP the way a desk phone does. Media is DTLS-SRTP, negotiated with ICE, often via a gateway into SIP.","cite":"RFC 8825 family, WebRTC","layout":"ladder","actors":["Browser","Gateway","SIP agent"],"chart":"mos","icon":"media","keys":[["DTLS-SRTP","Browser media"],["ICE","Path selection"],["Gateway","Correlation point"],["SIP Call-ID","Other leg"]],"header":null,"audio":true,"steps":[{"f":0,"t":1,"label":"SDP offer","kind":"req","cap":"The browser offers ICE candidates and DTLS-SRTP fingerprints."},{"f":1,"t":0,"label":"answer","kind":"ok","cap":"The gateway answers and anchors or translates the media toward the SIP side."},{"f":1,"t":2,"label":"SIP INVITE","kind":"req","cap":"The SIP leg is a normal INVITE. Its Call-ID will not equal the browser peer connection id. You need the gateway's correlation."},{"f":0,"t":1,"label":"DTLS-SRTP","kind":"media","cap":"If ICE fails, the SIP leg can still look answered while the browser sends nothing."}]},{"id":"cube-b2bua","title":"CUBE as a B2BUA","why":"CUBE terminates one SIP dialog and starts another. Call-IDs differ per leg. In flow-through mode, RTP anchors on CUBE so it can do SRTP, transcoding, and recording.","cite":"Cisco IOS XE CUBE configuration guide","layout":"ladder","actors":["CUCM","CUBE","ITSP"],"chart":"codec","icon":"cube","keys":[["Two Call-IDs","B2BUA"],["Dial-peer","Both legs"],["Flow-through","RTP on CUBE"],["MTP","Only if required"]],"header":"sdp","audio":true,"steps":[{"f":0,"t":1,"label":"INVITE leg A","kind":"req","cap":"CUCM sends INVITE to the dial-peer that targets CUBE. This Call-ID belongs to leg A."},{"f":1,"t":0,"label":"100 Trying","kind":"prov","cap":"CUBE answers 100 on leg A while it hunts an outbound dial-peer."},{"f":1,"t":2,"label":"INVITE leg B","kind":"req","cap":"CUBE sends a new INVITE to the ITSP. New Call-ID, new From tag. Early offer or delayed offer follows the dial-peer."},{"f":2,"t":1,"label":"180 / 183","kind":"prov","cap":"The ITSP alerts or sends early media. CUBE translates that into a response on leg A."},{"f":1,"t":0,"label":"180 / 183","kind":"prov","cap":"CUCM sees the translated response. Ringback is either local or the early RTP CUBE is anchoring."},{"f":2,"t":1,"label":"200 OK","kind":"ok","cap":"The ITSP answers leg B."},{"f":1,"t":0,"label":"200 OK","kind":"ok","cap":"CUBE answers leg A. Two dialogs are up."},{"f":0,"t":1,"label":"ACK","kind":"req","cap":"ACK is consumed on leg A and generated on leg B. It is not one end-to-end ACK."},{"f":1,"t":2,"label":"ACK","kind":"req","cap":"Leg B is confirmed."},{"f":0,"t":2,"label":"RTP via CUBE","kind":"media","cap":"With media flow-through, packets are Phone to CUBE to ITSP. CUCM is not in the audio path unless an MTP was inserted."},{"f":0,"t":1,"label":"BYE","kind":"bye","cap":"BYE on one leg is translated. CUBE clears the other leg."}]},{"id":"cube-delayed","title":"CUBE delayed offer to the provider","why":"Some providers require a delayed offer. CUBE can receive an early offer from CUCM and send a delayed offer onward. The ACK toward the provider then carries the answer.","cite":"RFC 3264 and CUBE SIP profiles","layout":"ladder","actors":["CUCM","CUBE","ITSP"],"chart":"codec","icon":"cube","keys":[["Early offer","SDP in INVITE"],["Delayed offer","SDP in 200"],["Answer","In the ACK"],["Profile","Do not strip the body you need"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"INVITE + SDP","kind":"req","cap":"CUCM early-offers to CUBE."},{"f":1,"t":2,"label":"INVITE","kind":"req","cap":"CUBE sends the ITSP an INVITE with no SDP because that dial-peer is delayed offer."},{"f":2,"t":1,"label":"200 + SDP","kind":"ok","cap":"The provider offers in the 200."},{"f":1,"t":2,"label":"ACK + SDP","kind":"req","cap":"CUBE answers in the ACK on leg B."},{"f":1,"t":0,"label":"200 OK","kind":"ok","cap":"Leg A is answered with an SDP that matches what CUBE can actually send."}]},{"id":"cube-failover","title":"Outbound dial-peer failover","why":"A preference list only helps if the failure is a response CUBE is willing to hunt on. A 200 OK to a black hole will not hunt.","cite":"Cisco CUBE dial-peer configuration","layout":"ladder","actors":["CUCM","CUBE","Peer A","Peer B"],"chart":"none","icon":"cube","keys":[["Preference","Hunt order"],["503","Often hunts"],["200 + silence","Does not hunt"],["OPTIONS","Can busy-out a peer"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"The inbound dial-peer matches."},{"f":1,"t":2,"label":"INVITE","kind":"req","cap":"Outbound dial-peer A is tried first."},{"f":2,"t":1,"label":"503","kind":"err","cap":"Peer A refuses. CUBE ACKs the 503 and may hunt if hunting is enabled for that cause."},{"f":1,"t":3,"label":"INVITE","kind":"req","cap":"Dial-peer B is next. The caller still has one dialog with CUBE."},{"f":3,"t":1,"label":"200 OK","kind":"ok","cap":"Peer B answers. Hunting stops."}]},{"id":"cube-ha","title":"CUBE box-to-box failover","why":"Active/standby CUBE shares a virtual address. Calls that were checkpointed can survive a switchover. Calls that were not checkpointed drop.","cite":"Cisco CUBE high availability","layout":"ladder","actors":["CUCM","Active","Standby"],"chart":"none","icon":"cube","keys":[["VIP","One address"],["Checkpoint","Mid-call state"],["RG","Redundancy group"],["Split brain","Two actives, one disaster"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"Signaling is aimed at the virtual IP, not at a box-specific address."},{"f":1,"t":2,"label":"checkpoint","kind":"note","cap":"The active box checkpoints the dialog to the standby when that feature is on."},{"f":1,"t":2,"label":"failover","kind":"err","cap":"The standby takes the virtual IP. A call without a checkpoint is cleared."},{"f":0,"t":2,"label":"RTP","kind":"media","cap":"Media resumes only for checkpointed calls, and only if both boxes were ready to anchor it."}]},{"id":"sbc-topo","title":"SBC topology choices","why":"The SBC is the policy point: topology hiding, media anchoring, and the only place you should rewrite SDP. A second rewrite by a firewall ALG undoes it.","cite":"SBC design practice","layout":"ladder","actors":["Inside","SBC","Outside"],"chart":"none","icon":"cube","keys":[["Flow-through","Anchor media"],["Flow-around","Bypass media"],["ALG","Leave it off"],["Public c=","The outside address"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"Inside addresses and headers are still the enterprise view."},{"f":1,"t":2,"label":"INVITE","kind":"req","cap":"The SBC hides topology: new Call-ID, stripped internal headers, public c= line."},{"f":0,"t":1,"label":"RTP","kind":"media","cap":"Flow-through anchors media. Flow-around lets RTP bypass the SBC and then the SBC cannot record or transcode it."},{"f":2,"t":1,"label":"RTCP","kind":"media","cap":"If you need end-to-end RTCP XR, topology hiding and media anchoring change what the probes can see."}]},{"id":"cucm-route","title":"CUCM route pattern","why":"Digit analysis searches the line CSS first, then the device CSS. The first match wins. A pattern that is too wide steals calls from a more specific one that appears later.","cite":"Cisco Unified CM dial-plan guide","layout":"ladder","actors":["Phone","Line CSS","Device CSS","Route list","Trunk"],"chart":"none","icon":"route","keys":[["Line CSS","Searched first"],["Device CSS","Searched second"],["Partition","Where the pattern lives"],["Route list","Hunt the trunks"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"digits","kind":"note","cap":"The phone sends the dialed digits in the INVITE Request-URI."},{"f":1,"t":2,"label":"CSS order","kind":"note","cap":"CUCM concatenates the line CSS and then the device CSS. Partitions are searched in that order."},{"f":2,"t":3,"label":"pattern","kind":"note","cap":"The first matching translation or route pattern wins, including its urgent priority."},{"f":3,"t":4,"label":"route group","kind":"note","cap":"A route list tries route groups in order. The group picks a trunk or gateway member."},{"f":4,"t":4,"label":"INVITE","kind":"req","cap":"CUCM sends the INVITE with calling and called transformations from the pattern and the route group."}]},{"id":"cucm-onnet","title":"CUCM on-net call","why":"Two phones on the same cluster signal through CUCM and send RTP to each other. CUCM is not in the audio path unless an MTP, transcoder, or TRP is invoked.","cite":"Cisco Unified CM","layout":"ladder","actors":["Phone A","CUCM","Phone B"],"chart":"codec","icon":"phone","keys":[["DN","Directory number"],["Partition","Visibility"],["MTP","CUCM in media"],["RTP","Phone to phone"]],"header":null,"audio":true,"steps":[{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"Phone A is registered. The INVITE hits CUCM."},{"f":1,"t":1,"label":"DA","kind":"note","cap":"Digit analysis finds Phone B's directory number in a partition Phone A's CSS can see."},{"f":1,"t":2,"label":"INVITE","kind":"req","cap":"CUCM calls Phone B. This is a new leg."},{"f":2,"t":1,"label":"180","kind":"prov","cap":"Phone B rings."},{"f":2,"t":1,"label":"200","kind":"ok","cap":"Phone B answers."},{"f":1,"t":0,"label":"200","kind":"ok","cap":"CUCM answers Phone A."},{"f":0,"t":2,"label":"RTP","kind":"media","cap":"RTP goes phone to phone. If you see CUCM's address in SDP, an MTP was inserted."}]},{"id":"cucm-reg","title":"Phone registration","why":"A phone that cannot register cannot place a reliable call. The path is PoE and VLAN, DHCP options, then TFTP or HTTPS config, then SIP or SCCP registration.","cite":"Cisco endpoint and CUCM docs","layout":"ladder","actors":["Phone","DHCP","TFTP","CUCM"],"chart":"none","icon":"phone","keys":[["DHCP 150","TFTP list"],["6970","CUCM HTTP files"],["5060","SIP register"],["2000","SCCP"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"DHCP","kind":"note","cap":"The phone needs an address and option 150 or 66 for the TFTP server, unless it was staged with a name."},{"f":1,"t":2,"label":"TFTP 6970","kind":"note","cap":"CUCM serves phone files on UDP 69 and HTTP 6970. The file names the CUCM nodes."},{"f":2,"t":3,"label":"REGISTER","kind":"req","cap":"A SIP phone sends REGISTER. An SCCP phone uses TCP 2000. TLS uses the secure ports configured on the cluster."},{"f":3,"t":0,"label":"200 OK","kind":"ok","cap":"The phone is registered. Until this 200, a dialed call is a local failure, not a dial-plan failure."}]},{"id":"cucm-srst","title":"SRST fallback","why":"When the phone loses CUCM, SRST on the gateway keeps a subset of dialing alive. When CUCM returns, phones must re-home. A phone stuck in SRST is a WAN-recovery fault.","cite":"Cisco SRST","layout":"ladder","actors":["Phone","WAN","SRST","CUCM"],"chart":"none","icon":"phone","keys":[["Keepalive","Loss starts the timer"],["SRST","Local dial tone"],["Re-home","Back to CUCM"],["Feature loss","Expected while fallen back"]],"header":null,"audio":false,"steps":[{"f":0,"t":3,"label":"keepalive","kind":"note","cap":"The phone watches CUCM. Missed keepalives start the fallback timer."},{"f":0,"t":2,"label":"fallback","kind":"err","cap":"The phone registers to the local SRST router. Only the configured dial peers and a limited feature set exist."},{"f":3,"t":0,"label":"CUCM returns","kind":"ok","cap":"When the WAN path to CUCM works again, the phone re-registers to the cluster and leaves SRST."}]},{"id":"cucm-em","title":"Extension Mobility","why":"Extension Mobility swaps the device profile onto the phone. The line CSS can change at login. A failure after login is often the user profile, not the phone's device CSS.","cite":"Cisco Extension Mobility","layout":"ladder","actors":["User","Phone","CUCM"],"chart":"none","icon":"phone","keys":[["Device profile","What login applies"],["Line CSS","Searched first"],["Logout profile","The empty phone"],["EMCC","Cross-cluster is a separate design"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"login","kind":"note","cap":"The user signs in on the phone or through the service."},{"f":1,"t":2,"label":"profile","kind":"note","cap":"CUCM applies the device profile: lines, CSS, and softkeys."},{"f":2,"t":1,"label":"reset line","kind":"ok","cap":"The line registers with the profile's directory number. Calls now use that line CSS first."},{"f":0,"t":1,"label":"logout","kind":"note","cap":"Logout restores the logout profile. A phone left logged in keeps the previous user's class of service."}]},{"id":"cucm-hunt","title":"Hunt group","why":"A hunt pilot has its own CSS, then a line group. A loop happens when a member forwards back to the pilot. RNA must land somewhere that does not return.","cite":"Cisco Unified CM hunt lists","layout":"ladder","actors":["Caller","Hunt pilot","Line group","Member"],"chart":"none","icon":"queue","keys":[["Pilot","The number"],["Line group","The members"],["RNA","Must exit"],["Hunt CSS","Not the caller's CSS"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"The pilot number matches."},{"f":1,"t":2,"label":"algorithm","kind":"note","cap":"The line group rings the next member by broadcast, longest idle, or circular order."},{"f":2,"t":3,"label":"ring","kind":"prov","cap":"The member rings. RNA advances only if the hunt is allowed to try the next member."},{"f":3,"t":1,"label":"RNA","kind":"err","cap":"If the member's forward-no-answer target is the pilot, the hunt loops. Point RNA at a final destination."}]},{"id":"cucm-moh","title":"Music on hold","why":"Hold is a re-INVITE. The MOH audio is a stream from the MOH server, selected by the holder's source. Silence on hold means that stream is not reaching the held party.","cite":"Cisco MOH","layout":"ladder","actors":["Holder","CUCM","MOH","Held"],"chart":"codec","icon":"media","keys":[["User source","Which audio"],["Multicast","Network must carry it"],["Unicast","One stream"],["Hold re-INVITE","The trigger"]],"header":null,"audio":true,"steps":[{"f":0,"t":1,"label":"re-INVITE","kind":"req","cap":"The holder sends a hold re-INVITE."},{"f":1,"t":2,"label":"select","kind":"note","cap":"CUCM picks the MOH source from the user's audio source or the default."},{"f":2,"t":3,"label":"RTP","kind":"media","cap":"MOH RTP is sent to the held party's address. Multicast MOH requires the network to carry that group. Unicast MOH is a normal stream."},{"f":0,"t":1,"label":"resume","kind":"ok","cap":"A second re-INVITE restores sendrecv and stops the MOH stream."}]},{"id":"cucm-conf","title":"Conference bridge","why":"An ad-hoc conference allocates a bridge resource. When the bridge is full, the conference fails even though both calls were fine alone.","cite":"Cisco conferencing","layout":"ladder","actors":["Host","CUCM","Bridge","Parties"],"chart":"erlang","icon":"media","keys":[["MRGL","Which resources"],["Bridge port","One per party"],["Mixer","RTP to the bridge"],["Exhausted","A capacity fault"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"Conf","kind":"note","cap":"The host presses conference. CUCM needs a media resource from the host's MRGL."},{"f":1,"t":2,"label":"allocate","kind":"note","cap":"A software or hardware bridge port is reserved. Exhaustion returns a failure, not a new dial tone."},{"f":2,"t":3,"label":"RTP","kind":"media","cap":"Each party sends RTP to the bridge, not to each other. The bridge mixes."},{"f":0,"t":1,"label":"drop","kind":"bye","cap":"When the host drops, the remaining parties follow the conference drop policy."}]},{"id":"cucm-mtp","title":"When an MTP is inserted","why":"An MTP anchors media on CUCM. It is required for some DTMF and protocol mismatches. It is also a capacity limit and a single place for one-way audio.","cite":"Cisco media resources","layout":"ladder","actors":["Phone","MTP","Trunk"],"chart":"codec","icon":"media","keys":[["MRGL","Where the MTP lives"],["SDP c=","MTP address"],["DTMF","A common reason"],["Sessions","A hard cap"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"CUCM decides an MTP is required, often for DTMF or early offer conversion."},{"f":1,"t":2,"label":"INVITE","kind":"req","cap":"The trunk side sees the MTP address in SDP, not the phone."},{"f":0,"t":1,"label":"RTP","kind":"media","cap":"Phone sends RTP to the MTP."},{"f":1,"t":2,"label":"RTP","kind":"media","cap":"The MTP sends RTP to the trunk. If the MTP is out of sessions, the call fails or proceeds without the feature you needed."}]},{"id":"unity-mwi","title":"Unity Connection and MWI","why":"Forward to voicemail is a call forward, then a SIP or SCCP integration. The message-waiting lamp is a separate notify. A caller who reached voicemail did not prove that MWI works.","cite":"Cisco Unity Connection","layout":"ladder","actors":["CUCM","Unity","Phone"],"chart":"none","icon":"phone","keys":[["Pilot","Voicemail number"],["Redirecting","Which mailbox"],["MWI","Separate signal"],["Pilot CSS","Must reach Unity"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"forward","kind":"req","cap":"CUCM forwards the unanswered call to the voicemail pilot."},{"f":1,"t":1,"label":"greeting","kind":"media","cap":"Unity plays the greeting and takes the message. The redirecting number selects the mailbox."},{"f":1,"t":0,"label":"MWI","kind":"note","cap":"Unity tells CUCM to light the lamp. CUCM notifies the phone. A failure here leaves a message and a dark lamp."},{"f":2,"t":1,"label":"retrieve","kind":"req","cap":"The user dials the pilot. The calling number selects the mailbox."}]},{"id":"cucm-cli","title":"CUCM command line checks","why":"The appliance shell is how you prove NTP, replication, certificates, and disk without guessing from the GUI. These commands read state. They are not a Linux course.","cite":"Cisco Unified OS administration","layout":"ladder","actors":["Admin","Publisher"],"chart":"none","icon":"cert","keys":[["NTP","First"],["Replication","Second"],["Disk","Logging partition"],["Cert","Expiry and trust"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"utils ntp status","kind":"note","cap":"Clock skew breaks certificates and CDRs. Look for a synchronized source."},{"f":0,"t":1,"label":"utils dbreplication runtimestate","kind":"note","cap":"A pattern that exists on the publisher and not on a subscriber is often replication, not CSS."},{"f":0,"t":1,"label":"show status","kind":"note","cap":"Disk, CPU, and load. A full logging partition stops CDR and can destabilize the node."},{"f":0,"t":1,"label":"show cert list","kind":"note","cap":"Confirm the certificate you think the phone trusts is the one installed, and note the expiry."}]},{"id":"cucm-failover","title":"CUCM node failover","why":"Phones keep a list of CUCM nodes. When the primary stops answering, they register to the next. Active calls may survive. New calls wait for the re-register.","cite":"Cisco Unified CM groups","layout":"ladder","actors":["Phone","Subscriber A","Subscriber B"],"chart":"none","icon":"phone","keys":[["CM group","Ordered list"],["Fallback","Timer, not instant"],["Active RTP","May continue"],["Re-home","When A returns"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"REGISTER","kind":"req","cap":"The phone is on subscriber A, the first server in its Unified CM group."},{"f":1,"t":0,"label":"silence","kind":"err","cap":"A stops responding. The phone waits through its fallback timer."},{"f":0,"t":2,"label":"REGISTER","kind":"req","cap":"The phone registers to subscriber B."},{"f":0,"t":2,"label":"INVITE","kind":"req","cap":"New calls use B. A call that was already up can continue phone to phone until a feature needs CUCM."}]},{"id":"mra-register","title":"Mobile and Remote Access registration","why":"MRA has two Expressway roles. The phone trusts the Expressway edge certificate, then traverses to the core, then registers to CUCM. A missing intermediate on the edge fails before CUCM sees a REGISTER.","cite":"Cisco Expressway MRA","layout":"ladder","actors":["Client","Expressway-E","Expressway-C","CUCM"],"chart":"none","icon":"cert","keys":[["Exp-E","Public edge"],["Exp-C","Inside"],["Chain","Send intermediates"],["Traversal","Both zones up"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"TLS","kind":"req","cap":"The client connects to Expressway-E on the public name. The certificate chain must include intermediates."},{"f":1,"t":2,"label":"traversal","kind":"note","cap":"E traverses to C over the traversal zone. Both zones must be up."},{"f":2,"t":3,"label":"REGISTER","kind":"req","cap":"C presents the registration to CUCM. CUCM must list the traversal domain."},{"f":3,"t":0,"label":"200 OK","kind":"ok","cap":"The client is registered. Service discovery and registration are different steps. A domain that resolves is not a registration."}]},{"id":"mra-call","title":"MRA call media","why":"On MRA, media often hairpins on Expressway. A call that registers and then has no audio is a traversal media path, a firewall port, or an ICE failure, not a CSS problem.","cite":"Cisco Expressway MRA","layout":"ladder","actors":["Remote","Expressway","Inside phone"],"chart":"mos","icon":"media","keys":[["Traversal","Media ports"],["TURN","If ICE needs it"],["CSS","Still CUCM's job"],["No audio","After a good REGISTER"]],"header":null,"audio":true,"steps":[{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"Signaling traverses E and C to CUCM, then to the inside phone."},{"f":1,"t":2,"label":"INVITE","kind":"req","cap":"CUCM completes digit analysis as usual."},{"f":0,"t":1,"label":"RTP","kind":"media","cap":"Media is anchored or traversed at Expressway. The firewall must allow that media range."},{"f":1,"t":2,"label":"RTP","kind":"media","cap":"The inside phone sends RTP toward Expressway, not toward the remote private address."}]},{"id":"e164","title":"E.164 and directory numbers","why":"Store a global number and present a local one. The dial plan normalizes what the user dialed into the form the route pattern expects. Mixed forms cause partial matches.","cite":"E.164 and CUCM dial-plan practice","layout":"ladder","actors":["User dials","Translation","Route"],"chart":"none","icon":"route","keys":[["+E.164","Global form"],["Translation","Normalize first"],["Presentation","What the provider sees"],["CSS","Must include the pattern"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"+E.164","kind":"note","cap":"A directory number or a pattern in global form, with a leading plus, is unambiguous."},{"f":1,"t":1,"label":"normalize","kind":"note","cap":"A translation pattern strips access codes and adds the country code before the route pattern sees the digits."},{"f":1,"t":2,"label":"route","kind":"req","cap":"The route pattern matches the normalized number. The gateway may need a different presentation for the provider."}]},{"id":"dial-plan","title":"Dial-plan order","why":"Urgent patterns, translations, and the CSS order decide which pattern wins. A test call that matches the wrong pattern is working as configured.","cite":"Cisco Unified CM dial plan","layout":"ladder","actors":["Digits","Translation","Route pattern","Gateway"],"chart":"none","icon":"route","keys":[["Urgent","Skip the wait"],["Translation","Can restart"],["CSS order","Line then device"],["Discard digits","PreDot and others"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"analyze","kind":"note","cap":"CUCM waits for inter-digit timeout unless the match is urgent."},{"f":1,"t":2,"label":"transform","kind":"note","cap":"Translation patterns change digits and can restart analysis."},{"f":2,"t":3,"label":"route","kind":"req","cap":"The winning route pattern selects the route list."},{"f":3,"t":3,"label":"called party","kind":"note","cap":"The gateway or trunk transformation is the last change before the provider."}]},{"id":"wx-lgw-out","title":"Webex Calling outbound via Local Gateway","why":"The Webex app signals Webex Calling, not the gateway. The gateway is a trunk the location uses for premises PSTN. CUBE is still a B2BUA toward the carrier.","cite":"Webex Calling port reference and Local Gateway guide","layout":"ladder","actors":["Webex app","Webex Calling","Local Gateway","PSTN"],"chart":"codec","icon":"cloud","keys":[["TCP 5062","Certificate trunk to Webex"],["TCP 8934","Registration trunk"],["Listen port","You choose, certificate inbound"],["SRTP","Cloud side"]],"header":"sdp","audio":true,"steps":[{"f":0,"t":1,"label":"dial","kind":"req","cap":"The app sends the call into Webex Calling. The location decides the PSTN path."},{"f":1,"t":2,"label":"SIP TLS","kind":"req","cap":"Certificate-based trunks: the gateway sends SIP TLS to Webex Calling on TCP 5062, and Webex Calling connects to the listen port you set. Registration-based trunks: the gateway registers toward TCP 8934 and that session is reused."},{"f":2,"t":3,"label":"INVITE","kind":"req","cap":"The Local Gateway, usually CUBE, places a new call leg to the ITSP or to CUCM. New Call-ID."},{"f":3,"t":2,"label":"18x / 200","kind":"ok","cap":"Progress and answer return on the PSTN leg."},{"f":2,"t":1,"label":"18x / 200","kind":"ok","cap":"CUBE translates them toward Webex Calling."},{"f":0,"t":3,"label":"SRTP / RTP","kind":"media","cap":"Media between Webex and the gateway is SRTP. The PSTN leg is whatever that peer negotiated. Webex Calling is not a silent extra RTP hop you can ignore."}]},{"id":"wx-lgw-in","title":"Webex Calling inbound via Local Gateway","why":"An inbound PSTN call hits the gateway first, then Webex Calling, then the user. The called number must be a number Webex Calling owns for that location.","cite":"Webex Calling Local Gateway","layout":"ladder","actors":["PSTN","Local Gateway","Webex Calling","User"],"chart":"none","icon":"cloud","keys":[["Called number","Must match Webex"],["Trunk","Location PSTN"],["B2BUA","Two Call-IDs"],["SRTP","Toward Webex"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"The carrier sends the inbound call to the gateway."},{"f":1,"t":2,"label":"INVITE","kind":"req","cap":"The gateway sends it to Webex Calling over the trunk. The called number is the Webex Calling number, in the form the trunk expects."},{"f":2,"t":3,"label":"alert","kind":"prov","cap":"Webex Calling alerts the app or the desk device."},{"f":3,"t":2,"label":"200 OK","kind":"ok","cap":"The user answers. ACK is per leg because the gateway is a B2BUA."},{"f":0,"t":3,"label":"media","kind":"media","cap":"SRTP on the Webex side, carrier media on the PSTN side, anchored on the gateway when you flow through."}]},{"id":"wx-plan","title":"Webex Calling plan","why":"A Cisco Calling Plan keeps PSTN inside Webex Calling. There is no Local Gateway on that call. If you expected the CUBE to see it, the location is not using premises PSTN.","cite":"Webex Calling PSTN options","layout":"ladder","actors":["User","Webex Calling","Cisco PSTN"],"chart":"none","icon":"cloud","keys":[["Calling plan","Cloud PSTN"],["Premises","Local Gateway instead"],["Location","The switch"],["CUBE trace","Empty on purpose"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"dial","kind":"req","cap":"The user dials. The location's PSTN connection is a calling plan, not a premises trunk."},{"f":1,"t":2,"label":"PSTN","kind":"req","cap":"Webex Calling hands the call to the Cisco calling-plan carrier."},{"f":2,"t":1,"label":"200 OK","kind":"ok","cap":"Answer returns inside the cloud path."},{"f":0,"t":1,"label":"media","kind":"media","cap":"Media stays on the Webex Calling media path. A CUBE trace will be empty, and that is expected."}]},{"id":"teams-dr-out","title":"Teams Direct Routing outbound","why":"The Teams client talks to Phone System. Phone System selects an SBC from the voice routing policy. The SBC then places the PSTN leg. Media bypass is optional and separate.","cite":"Microsoft Learn, Plan Direct Routing","layout":"ladder","actors":["Teams client","Phone System","SBC","PSTN"],"chart":"codec","icon":"team","keys":[["5061","SBC to Microsoft"],["SipSignalingPort","Microsoft to SBC"],["sip.pstnhub","Primary FQDN"],["Bypass","Separate media path"]],"header":"sdp","audio":true,"steps":[{"f":0,"t":1,"label":"dial","kind":"req","cap":"The client signals Microsoft 365, not the SBC."},{"f":1,"t":1,"label":"route","kind":"note","cap":"The online voice routing policy, PSTN usage, and route pick the SBC."},{"f":1,"t":2,"label":"INVITE","kind":"req","cap":"Phone System sends SIP TLS to the SBC FQDN on the port you set as SipSignalingPort. The SBC sends SIP TLS to sip.pstnhub.microsoft.com on 5061, and can fail over to sip2 and sip3."},{"f":2,"t":3,"label":"INVITE","kind":"req","cap":"The SBC, a B2BUA, places the carrier leg with its own Call-ID."},{"f":3,"t":2,"label":"200 OK","kind":"ok","cap":"The carrier answers."},{"f":2,"t":0,"label":"media","kind":"media","cap":"Without media bypass, media goes through a Teams media processor (UDP 3478\u20133481 and 49152\u201353247). With media bypass, a supported path can run direct from client to SBC."}]},{"id":"teams-dr-in","title":"Teams Direct Routing inbound","why":"The carrier hits your SBC. The SBC sends the INVITE to Microsoft on 5061. The number must be assigned to a user or a resource account that the voice route can reach.","cite":"Microsoft Learn, Direct Routing","layout":"ladder","actors":["PSTN","SBC","Phone System","Teams user"],"chart":"none","icon":"team","keys":[["5061","Toward Microsoft"],["Resource account","Queues and attendants"],["SBC cert","Public name"],["OPTIONS","Trunk health"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"Inbound PSTN arrives at the certified SBC."},{"f":1,"t":2,"label":"INVITE :5061","kind":"req","cap":"The SBC sends SIP TLS to the Phone System FQDN on port 5061."},{"f":2,"t":3,"label":"alert","kind":"prov","cap":"Teams alerts the user or the call queue resource account."},{"f":3,"t":2,"label":"200 OK","kind":"ok","cap":"Answer. Media follows bypass or the media processor, same as outbound."}]},{"id":"teams-options","title":"Teams OPTIONS and failover","why":"Direct Routing uses SIP OPTIONS as a heartbeat. If OPTIONS fails, new calls leave that SBC. Existing calls are a different question.","cite":"Microsoft Learn, Direct Routing","layout":"ladder","actors":["SBC","sip","sip2","sip3"],"chart":"none","icon":"team","keys":[["OPTIONS","Heartbeat"],["sip / sip2 / sip3","Three FQDNs"],["5061","SBC source to Microsoft"],["Enabled","A drained SBC takes no new calls"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"OPTIONS","kind":"req","cap":"The SBC probes sip.pstnhub.microsoft.com."},{"f":1,"t":0,"label":"200 OK","kind":"ok","cap":"A 200 keeps the trunk eligible."},{"f":0,"t":1,"label":"timeout","kind":"err","cap":"Missed OPTIONS mark the path down."},{"f":0,"t":2,"label":"OPTIONS","kind":"req","cap":"The SBC fails over to sip2, then sip3. Signaling failover is not the same as media bypass."}]},{"id":"teams-bypass","title":"Teams media bypass","why":"Media bypass lets the client send SRTP directly to the SBC when the network allows it. The signaling path does not change. A firewall that allows 5061 and blocks the media range looks like a successful call with no audio.","cite":"Microsoft Learn, media bypass","layout":"ladder","actors":["Teams client","SBC","Media processor"],"chart":"mos","icon":"media","keys":[["Signaling","Unchanged"],["Bypass on","Client to SBC"],["Processor","The fallback"],["IPv6","Bypass is not supported on IPv6"]],"header":null,"audio":true,"steps":[{"f":0,"t":1,"label":"signaling","kind":"req","cap":"Signaling still goes through Phone System to the SBC."},{"f":0,"t":1,"label":"SRTP direct","kind":"media","cap":"With bypass on, and a candidate that works, media is client to SBC."},{"f":0,"t":2,"label":"SRTP relay","kind":"media","cap":"Without bypass, or when the direct path fails, media uses the Teams media processor."},{"f":1,"t":1,"label":"PSTN","kind":"note","cap":"The SBC still has a separate PSTN media leg. Bypass does not remove the carrier."}]},{"id":"teams-plan","title":"Teams Calling Plan and Operator Connect","why":"Calling Plan and Operator Connect do not use your Direct Routing SBC. A trace on that SBC will be empty. The number's PSTN type is the first fact to collect.","cite":"Microsoft Teams PSTN connectivity","layout":"ladder","actors":["User","Phone System","PSTN provider"],"chart":"none","icon":"team","keys":[["Calling Plan","Microsoft carrier"],["Operator Connect","Your operator"],["Direct Routing","Your SBC"],["Number type","Check it first"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"dial","kind":"req","cap":"The user dials. Phone System looks at the number's PSTN connectivity."},{"f":1,"t":2,"label":"provider","kind":"req","cap":"Calling Plan uses Microsoft's carrier. Operator Connect uses the operator you selected. Direct Routing would have used your SBC instead."},{"f":2,"t":1,"label":"answer","kind":"ok","cap":"Answer and media stay on that provider path."}]},{"id":"walk-call-setup","title":"End-to-end call setup","why":"This is the walkthrough to replay on a bridge: phone to CUCM, CUCM to CUBE, CUBE to the carrier, then RTP that skips CUCM.","cite":"RFC 3261 and Cisco CUCM plus CUBE","layout":"ladder","actors":["Phone","CUCM","CUBE","PSTN"],"chart":"qos","icon":"route","keys":[["3 Call-IDs","Phone, CUCM, CUBE"],["CSS","Line then device"],["Flow-through","RTP on CUBE"],["ACK","Per leg"]],"header":"sdp","audio":true,"steps":[{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"The phone sends an early-offer INVITE to CUCM."},{"f":1,"t":1,"label":"digit analysis","kind":"note","cap":"Line CSS, then device CSS. The route pattern points at a route list and a SIP trunk to CUBE."},{"f":1,"t":2,"label":"INVITE","kind":"req","cap":"CUCM sends a new INVITE to CUBE. CUCM is a back-to-back user agent here."},{"f":2,"t":3,"label":"INVITE","kind":"req","cap":"CUBE matches an outbound dial-peer and sends another INVITE to the provider. Third Call-ID."},{"f":3,"t":2,"label":"100 Trying","kind":"prov","cap":"The provider accepts the request for processing."},{"f":3,"t":2,"label":"180 or 183","kind":"prov","cap":"180 is local ringback. 183 with SDP is early media. Know which one you asked for."},{"f":2,"t":1,"label":"18x","kind":"prov","cap":"CUBE translates the response toward CUCM."},{"f":1,"t":0,"label":"18x","kind":"prov","cap":"The phone rings or plays the early stream."},{"f":3,"t":2,"label":"200 OK","kind":"ok","cap":"The called party answers."},{"f":2,"t":1,"label":"200 OK","kind":"ok","cap":"CUBE answers CUCM."},{"f":1,"t":0,"label":"200 OK","kind":"ok","cap":"CUCM answers the phone. Each leg gets its own ACK."},{"f":0,"t":2,"label":"ACK","kind":"req","cap":"ACK stops at each B2BUA and is regenerated. Do not look for one ACK across all three Call-IDs."},{"f":0,"t":3,"label":"RTP","kind":"media","cap":"Audio is phone to CUBE to provider when CUBE is flow-through. CUCM's IP should not appear in the media path."},{"f":0,"t":1,"label":"BYE","kind":"bye","cap":"Hangup clears each leg in turn."}]},{"id":"walk-failover","title":"Signaling failover walkthrough","why":"Failover is a timer plus a second path. Practice which calls die and which calls move before you promise a customer that nothing drops.","cite":"CUCM groups and CUBE HA","layout":"ladder","actors":["Phone","Primary","Secondary"],"chart":"none","icon":"migration","keys":[["Timer","Not instant"],["Next peer","Must be configured"],["New calls","After register"],["Mid-call","Only if checkpointed"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"steady","kind":"ok","cap":"Registration and the active dialog sit on the primary."},{"f":1,"t":0,"label":"failure","kind":"err","cap":"The primary stops. Keepalives fail. This is not instantaneous."},{"f":0,"t":2,"label":"re-register","kind":"req","cap":"The phone or the trunk uses the next configured peer."},{"f":0,"t":2,"label":"new call","kind":"ok","cap":"New calls work after registration. A mid-call that was not checkpointed drops and must be redialed."}]},{"id":"ucce-comp","title":"UCCE comprehensive call","why":"CVP stays in the signaling path, asks ICM for instructions, and extends a VRU leg to Cisco VVB. The agent leg is another transfer. CUIC is not in the audio path.","cite":"Cisco CVP 15 configuration guide, comprehensive model","layout":"ladder","actors":["Ingress","CVP","ICM","VVB","Agent"],"chart":"kpi","icon":"queue","keys":[["Switch leg","Ingress to CVP"],["VRU leg","CVP to VVB"],["re-INVITE","CVP stays"],["Finesse","Agent desktop"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"SIP INVITE","kind":"req","cap":"The ingress gateway sends the call to the CVP call server. This is the switch leg."},{"f":1,"t":2,"label":"route request","kind":"note","cap":"CVP, as routing client, asks ICM over the VRU PG. ICM runs the script."},{"f":2,"t":1,"label":"Send to VRU","kind":"note","cap":"Send to VRU returns a VRU label. Type 10 Network VRU is the model Cisco documents to simplify this handoff. A correlation id matches the VRU leg on the models that use one."},{"f":1,"t":3,"label":"VRU leg","kind":"req","cap":"CVP extends the call to Cisco VVB, usually with a re-INVITE, so CVP stays in signaling and keeps the call license. REFER would step CVP out."},{"f":3,"t":3,"label":"VoiceXML","kind":"media","cap":"VVB fetches VoiceXML from the CVP VXML server and plays prompts or collects digits."},{"f":2,"t":1,"label":"agent label","kind":"note","cap":"When an agent is ready, ICM returns an agent label."},{"f":1,"t":4,"label":"to CUCM","kind":"req","cap":"CVP transfers to the agent DN on CUCM. The phone rings. Finesse shows the call."},{"f":4,"t":0,"label":"RTP","kind":"media","cap":"Audio is between the caller side and the agent. CUIC reads reporting data beside this path. It does not carry the voice."}]},{"id":"ucce-rona","title":"UCCE ring-no-answer","why":"RONA returns the call to the queue when the agent does not answer. If the script has nowhere to go, the caller sits in silence or the call drops.","cite":"Cisco UCCE scripting","layout":"ladder","actors":["Caller","CVP","ICM","Agent"],"chart":"kpi","icon":"queue","keys":[["RNA timer","How long the phone rings"],["Requery","Script must handle it"],["Queue","Treatment again"],["Finesse","Agent goes not-ready in many designs"]],"header":null,"audio":false,"steps":[{"f":0,"t":3,"label":"ring","kind":"prov","cap":"The agent device rings and Finesse offers the call."},{"f":3,"t":2,"label":"no answer","kind":"err","cap":"The RNA timer expires."},{"f":2,"t":2,"label":"requery","kind":"note","cap":"ICM requeries. The script must queue again or send the call to another target."},{"f":2,"t":1,"label":"label","kind":"req","cap":"CVP moves the call to the next label. The caller should hear queue treatment, not dead air."}]},{"id":"pcce","title":"Packaged CCE path","why":"PCCE is UCCE in a packaged model with a fixed capacity and SPOG for administration. The call still runs CVP, ICM, and Finesse. The package does not remove the legs.","cite":"Cisco Packaged CCE design guide","layout":"ladder","actors":["Ingress","CVP","PCCE","Finesse"],"chart":"kpi","icon":"queue","keys":[["SPOG","Admin, not audio"],["2000/4000/12000","Packaged sizes"],["CVP","Still there"],["CUIC","Reporting beside the call"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"Ingress still lands on CVP."},{"f":1,"t":2,"label":"script","kind":"note","cap":"The packaged router runs the script. Capacity is the 2000, 4000, or 12000 agent model you bought, not an unbounded cluster."},{"f":2,"t":3,"label":"agent","kind":"ok","cap":"Finesse delivers the call. SPOG is how you administer. It is not a hop in the audio path."}]},{"id":"cuic","title":"CUIC is beside the call","why":"CUIC shows intervals and live data from the reporting path. A chart that moves does not prove the audio leg. A chart that does not move does not mean the call failed.","cite":"Cisco Unified Intelligence Center","layout":"ladder","actors":["Call","AW/HDS","CUIC"],"chart":"kpi","icon":"proof","keys":[["Interval","Historical"],["Live","A different feed"],["RouterCallKey","Join key"],["Not RTP","CUIC is not the path"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"write","kind":"note","cap":"ICM writes historical rows on the interval. Live data is a separate feed."},{"f":1,"t":2,"label":"query","kind":"note","cap":"CUIC runs a report. The join key is the routercallkey or the contact identifiers the report was built to use."},{"f":2,"t":2,"label":"read","kind":"note","cap":"Use the report to pick a call, then open the CVP and Finesse logs for that id. Do not debug RTP inside CUIC."}]},{"id":"cc-route","title":"Queue then agent","why":"Every contact center in this campus does the same four moves: identify the contact, run a flow, queue against a skill, deliver to an agent who is ready. The product names change. The proof does not.","cite":"Contact-center routing practice","layout":"ladder","actors":["Entry","Flow","Queue","Agent"],"chart":"kpi","icon":"queue","keys":[["Contact id","The join key"],["Queue","The wait"],["Ready","Agent state"],["RONA","Back to queue"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"arrive","kind":"req","cap":"A number, a chat, or a callback request creates a contact with an id."},{"f":1,"t":2,"label":"decide","kind":"note","cap":"The flow sets attributes and chooses a queue. Hours, holidays, and intent belong here."},{"f":2,"t":3,"label":"ready","kind":"ok","cap":"The longest-waiting contact goes to the longest-idle ready agent, or whatever the platform's selection is."},{"f":3,"t":3,"label":"RONA","kind":"err","cap":"If the agent does not answer, the contact returns to queue and the agent state must change or the same miss repeats."}]},{"id":"wxcc-in","title":"Webex Contact Center inbound","why":"A Webex Contact Center call hits an entry point, runs a Flow Designer flow, waits in a queue, and is offered to a team. The agent desktop is where you prove delivery.","cite":"Webex Contact Center administrator guide","layout":"ladder","actors":["Caller","Entry point","Flow","Queue","Agent"],"chart":"kpi","icon":"queue","keys":[["Entry point","The front door"],["Flow","Flow Designer"],["Team","Who can take it"],["Interaction","The id in the desktop"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"PSTN or Webex","kind":"req","cap":"The call arrives on the entry-point number. Telephony may be Webex Calling or the contact-center PSTN."},{"f":1,"t":2,"label":"flow","kind":"note","cap":"Flow Designer plays prompts, collects digits, and sets variables."},{"f":2,"t":3,"label":"queue","kind":"note","cap":"The contact waits against a queue tied to a team."},{"f":3,"t":4,"label":"offer","kind":"ok","cap":"A ready agent on that team is offered the contact. RONA returns it if they do not answer."},{"f":4,"t":0,"label":"media","kind":"media","cap":"Audio is between the caller and the agent desktop or device. The flow is not a mixer."}]},{"id":"wxcc-flow","title":"Webex CC flow steps","why":"A flow is a script with a start and a queue. If the queue activity is never reached, agents will be idle while callers hear treatment or nothing.","cite":"Webex Contact Center Flow Designer","layout":"ladder","actors":["Start","Hours","Prompt","Queue"],"chart":"kpi","icon":"queue","keys":[["Entry point","Binds the flow"],["Time zone","Hours"],["Queue activity","Required"],["RONA","After delivery"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"entry","kind":"note","cap":"The entry point selects this flow."},{"f":1,"t":2,"label":"open?","kind":"note","cap":"Hours and holiday checks branch first. A wrong time zone sends everyone to closed."},{"f":2,"t":3,"label":"queue","kind":"ok","cap":"Queue is the activity that creates wait time and makes agents eligible."},{"f":3,"t":3,"label":"agent","kind":"ok","cap":"Delivery is after the queue, not inside the prompt."}]},{"id":"connect-in","title":"Amazon Connect inbound","why":"Connect starts a contact flow on a claimed number, queues against a routing profile, and writes a contact trace record after the contact. ContactId is the key.","cite":"Amazon Connect administrator guide","layout":"ladder","actors":["Caller","Contact flow","Queue","Agent"],"chart":"kpi","icon":"cloud","keys":[["ContactId","Join key"],["Routing profile","Which queues"],["Available","Agent state"],["CTR","The record"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"number","kind":"req","cap":"The claimed phone number points at a contact flow."},{"f":1,"t":2,"label":"blocks","kind":"note","cap":"The flow sets attributes, checks hours, and transfers to a queue. A Lambda that runs past the block timeout takes the error branch."},{"f":2,"t":3,"label":"offer","kind":"ok","cap":"An agent with that queue in the routing profile, in Available state, is offered the contact."},{"f":3,"t":3,"label":"CTR","kind":"note","cap":"After the contact, the contact trace record carries ContactId, queue, and agent. That is the capture, not a guess from CloudWatch alone."}]},{"id":"genesys-in","title":"Genesys Cloud inbound","why":"An Architect flow answers the call, then a queue receives it. The conversation id is what you paste into a bridge.","cite":"Genesys Cloud resource center","layout":"ladder","actors":["Caller","Architect","Queue","Agent"],"chart":"kpi","icon":"cloud","keys":[["Conversation id","Join key"],["Architect","The flow"],["Queue","The wait"],["Schedule","Time zone included"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"DID","kind":"req","cap":"The number is assigned to an Architect inbound flow."},{"f":1,"t":2,"label":"transfer","kind":"note","cap":"The flow transfers to a queue. Schedules and emergency groups branch before that."},{"f":2,"t":3,"label":"ALERTING","kind":"ok","cap":"A matching agent is alerted. The conversation id stays stable across the transfer."},{"f":3,"t":3,"label":"connected","kind":"media","cap":"Audio connects. Wrap-up is after disconnect and is not part of the audio path."}]},{"id":"nice-in","title":"NICE CXone inbound","why":"A point of contact lands on a script. The script queues to a skill. The agent must have that skill and be available. The contact id joins the script log to the agent leg.","cite":"NICE CXone","layout":"ladder","actors":["Caller","Script","Skill","Agent"],"chart":"kpi","icon":"queue","keys":[["Point of contact","Entry"],["Skill","The queue"],["Contact id","Join key"],["Unavailable","Will not be offered"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"point of contact","kind":"req","cap":"The number or digital entry starts the script."},{"f":1,"t":2,"label":"queue","kind":"note","cap":"The script selects a skill and begins queue music or messages."},{"f":2,"t":3,"label":"deliver","kind":"ok","cap":"An available agent with the skill is offered the contact."},{"f":3,"t":3,"label":"contact id","kind":"note","cap":"Keep the contact id. Disposition and recording are after the conversation and use that id."}]},{"id":"five9-in","title":"Five9 inbound","why":"An inbound number maps to a campaign. The IVR script runs, then a skill is queued. The agent must be assigned to that skill.","cite":"Five9 administrator","layout":"ladder","actors":["Caller","Campaign","IVR","Skill","Agent"],"chart":"kpi","icon":"queue","keys":[["Campaign","Inbound container"],["DNIS","Number map"],["Skill","Queue"],["Call id","Desktop key"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"DNIS","kind":"req","cap":"The dialed number selects the inbound campaign."},{"f":1,"t":2,"label":"IVR","kind":"note","cap":"The script plays prompts and sets variables."},{"f":2,"t":3,"label":"skill","kind":"note","cap":"The skill is the queue."},{"f":3,"t":4,"label":"offer","kind":"ok","cap":"A ready agent assigned to the skill receives the call. The call id in the agent desktop is the capture key."}]},{"id":"twilio-in","title":"Twilio Flex inbound","why":"A number or SIP domain hits a Studio flow or a Function, which creates a TaskRouter task. Flex reserves a worker. Call SID and Task SID are different ids. Keep both.","cite":"Twilio Studio, TaskRouter, and Flex","layout":"ladder","actors":["Caller","Studio","TaskRouter","Flex"],"chart":"kpi","icon":"cloud","keys":[["Call SID","Voice leg"],["Task SID","Routing"],["Workflow","Queue choice"],["Worker","The agent"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"webhook","kind":"req","cap":"The number's voice URL runs Studio or a Function. A slow webhook retries and can double-create work."},{"f":1,"t":2,"label":"task","kind":"note","cap":"TaskRouter creates a task with attributes the workflow matches to a queue."},{"f":2,"t":3,"label":"reservation","kind":"ok","cap":"A worker with a matching activity is reserved. The Flex UI accepts or rejects."},{"f":3,"t":0,"label":"media","kind":"media","cap":"Audio is the Twilio voice leg. The task is the routing object. Do not expect one id to be both."}]},{"id":"zoom-phone","title":"Zoom Phone call","why":"Zoom Phone registers the device to Zoom, applies the site dial plan, and sends PSTN through Zoom or through a bring-your-own carrier peer. The carrier peer is not in the path when the site uses Zoom PSTN.","cite":"Zoom Phone administration","layout":"ladder","actors":["Device","Zoom Phone","PSTN or BYOC"],"chart":"none","icon":"cloud","keys":[["Site","Dial plan scope"],["BYOC","Your carrier peer"],["Zoom PSTN","No SBC of yours"],["Call log","The id in the admin portal"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"register","kind":"req","cap":"The phone or the app registers to Zoom Phone."},{"f":1,"t":1,"label":"dial plan","kind":"note","cap":"The site dial plan normalizes the number."},{"f":1,"t":2,"label":"PSTN","kind":"req","cap":"Zoom PSTN or the BYOC trunk takes the external leg. Internal users stay inside Zoom Phone."},{"f":0,"t":1,"label":"media","kind":"media","cap":"Media is between the device and Zoom, then onward. A BYOC SBC trace is empty unless that site uses BYOC."}]},{"id":"avaya-aura","title":"Avaya Aura SIP path","why":"Session Manager is the SIP core. Communication Manager still owns many station and trunk features. Adaptation on Session Manager can rewrite headers. A bad adaptation is a real outage.","cite":"Avaya Aura Session Manager and Communication Manager","layout":"ladder","actors":["Endpoint","Session Manager","Communication Manager","Trunk"],"chart":"none","icon":"route","keys":[["SM","SIP routing"],["CM","Features"],["Adaptation","Header rewrite"],["Entity link","Trust between servers"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"The endpoint sends INVITE to Session Manager."},{"f":1,"t":2,"label":"route","kind":"note","cap":"Sequencing and the dial pattern send the call to Communication Manager when CM must process it."},{"f":2,"t":3,"label":"trunk","kind":"req","cap":"CM or Session Manager sends the call to the trunk. Entity links and adaptations change headers here."},{"f":3,"t":2,"label":"200 OK","kind":"ok","cap":"Answer returns along the same sequence."}]},{"id":"ringcentral","title":"RingCentral call","why":"The device registers to RingCentral. The dial plan and the digital line live in the cloud. A bring-your-own carrier changes only the PSTN edge.","cite":"RingCentral admin","layout":"ladder","actors":["Device","RingCentral","PSTN"],"chart":"none","icon":"cloud","keys":[["Digital line","The user"],["Company number","Entry"],["Permissions","Class of service"],["Call log","Admin portal"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"register","kind":"req","cap":"The phone or app is online to RingCentral."},{"f":1,"t":1,"label":"dial","kind":"note","cap":"The user dials. The company dial plan and the user's permissions apply."},{"f":1,"t":2,"label":"PSTN","kind":"req","cap":"External calls use RingCentral PSTN or the connected carrier."},{"f":0,"t":1,"label":"media","kind":"media","cap":"Media goes to RingCentral. A local SBC capture stays empty unless you inserted one."}]},{"id":"eight-eight","title":"8x8 call","why":"8x8 is a cloud PBX. Registration, dial plan, and PSTN are in the 8x8 cloud unless you have a specific carrier interconnect. Prove the call with the 8x8 call id.","cite":"8x8 admin console","layout":"ladder","actors":["Device","8x8","PSTN"],"chart":"none","icon":"cloud","keys":[["Extension","User"],["Site","Dial scope"],["PSTN","8x8 or interconnect"],["Call id","Support capture"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"register","kind":"req","cap":"The endpoint is registered."},{"f":1,"t":2,"label":"route","kind":"req","cap":"Internal calls stay in 8x8. External calls take the configured PSTN."},{"f":2,"t":1,"label":"answer","kind":"ok","cap":"Answer and media return through 8x8."}]},{"id":"mitel","title":"Mitel hybrid call","why":"Mitel deployments are often a controller plus SIP trunks. Name the controller and the trunk. A cloud user and a premises set do not share a dial plan unless you built that integration.","cite":"Mitel administration","layout":"ladder","actors":["Set","Controller","SIP trunk"],"chart":"none","icon":"phone","keys":[["COS","Permissions"],["ARS","Route choice"],["SIP trunk","External"],["Anchor","Check SDP"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"seize","kind":"req","cap":"The set sends the call to the Mitel controller."},{"f":1,"t":1,"label":"dial","kind":"note","cap":"Class of service and the ARS or digit map select the route."},{"f":1,"t":2,"label":"INVITE","kind":"req","cap":"A SIP trunk carries the external call. It is a normal SIP dialog from here."},{"f":2,"t":0,"label":"RTP","kind":"media","cap":"Media may anchor on the controller or go direct, depending on the trunk programming."}]},{"id":"dialogflow","title":"Virtual agent then a person","why":"A virtual agent is a leg in front of the queue, not a replacement for the queue. When it must escape, it has to hand the same contact id and the collected slots to a person.","cite":"Dialogflow CX and contact-center telephony","layout":"ladder","actors":["Caller","Telephony","CX session","Agent"],"chart":"none","icon":"cloud","keys":[["Session id","CX join key"],["No-input","Not a SIP 408"],["Escalate","To a queue"],["Slots","Must survive the transfer"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"INVITE","kind":"req","cap":"The contact center or the gateway opens the virtual-agent leg."},{"f":1,"t":2,"label":"session","kind":"note","cap":"A CX session starts. The session id is the join key for prompts, intents, and latency."},{"f":2,"t":1,"label":"fulfill","kind":"media","cap":"Prompts stream back as audio. Barge-in and no-input are events, not SIP failures."},{"f":2,"t":3,"label":"escalate","kind":"req","cap":"Escalation transfers to a queue and must pass the session result. A transfer that drops the slots makes the agent start over."}]},{"id":"ccaas-generic","title":"CCaaS contact path","why":"If you do not know the product yet, still name the entry, the flow, the queue, and the agent id. Those four exist on every platform in this track.","cite":"Contact-center practice","layout":"ladder","actors":["Entry","Flow","Queue","Agent"],"chart":"kpi","icon":"cloud","keys":[["Entry","Number or channel"],["Flow","Decision"],["Queue","Wait"],["Agent id","Who got it"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"contact","kind":"req","cap":"Something creates a contact and an id."},{"f":1,"t":2,"label":"flow","kind":"note","cap":"A flow decides the queue."},{"f":2,"t":3,"label":"ready agent","kind":"ok","cap":"A ready agent with the skill receives it."},{"f":3,"t":3,"label":"id","kind":"note","cap":"Write the id down before you change anything."}]},{"id":"e911-cer","title":"Emergency Responder call","why":"CER learns the switch port, maps it to an ERL, and picks an ELIN so the PSAP can call back. CUCM must be able to route 911 to that path. On-site notification is a separate action.","cite":"Cisco Emergency Responder and Kari's Law","layout":"ladder","actors":["Phone","CUCM","CER","Gateway","PSAP"],"chart":"none","icon":"emergency","keys":[["911","Emergency pattern"],["ELIN","Callback number"],["ERL","Emergency response location"],["Kari","On-site notification"]],"header":null,"audio":false,"steps":[{"f":0,"t":2,"label":"discover","kind":"note","cap":"CER learns the phone's switch port, typically from switch discovery, and maps that port to an ERL."},{"f":0,"t":1,"label":"911","kind":"req","cap":"The phone dials 911. The calling search space must be able to reach the emergency pattern."},{"f":1,"t":2,"label":"route","kind":"note","cap":"CUCM routes the call to CER. CER selects the ELIN for that ERL."},{"f":2,"t":3,"label":"ELIN","kind":"req","cap":"The gateway sends the call onward with the ELIN as the calling number."},{"f":3,"t":4,"label":"PSAP","kind":"ok","cap":"The PSAP receives a callback number that ALI maps to a dispatchable location. Ray Baum's Act is why that location has to be specific."},{"f":2,"t":2,"label":"on-site","kind":"note","cap":"Kari's Law: someone on site is notified at the same time. That page or call is not the PSAP leg."}]},{"id":"e911-held","title":"Webex Calling emergency location","why":"The client asks the emergency service for a location with HELD, then the emergency call carries that location. A stale hotel network will return yesterday's building.","cite":"Webex Calling emergency calling, RFC 5985 HELD","layout":"ladder","actors":["Client","HELD","Webex Calling","PSAP"],"chart":"none","icon":"emergency","keys":[["HELD","Location request"],["BSSID / port","Network id"],["Civic","The address"],["On-site","Kari notification"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"HELD","kind":"note","cap":"The client sends a location request. The network identifier, BSSID, chassis port, or civic address selects the location."},{"f":1,"t":0,"label":"location","kind":"ok","cap":"A location comes back. If the network is unknown, the result is a default or a failure. Do not treat that as a successful test."},{"f":0,"t":2,"label":"911","kind":"req","cap":"The emergency call goes through Webex Calling with that location."},{"f":2,"t":3,"label":"PSAP","kind":"ok","cap":"The provider delivers the call and the location. On-site notification still has to fire for Kari's Law."}]},{"id":"e911-teams","title":"Teams dynamic emergency calling","why":"Teams matches the client network to an emergency address in the location information service. Direct Routing can add PIDF-LO only when the SBC and the gateway are set for it.","cite":"Microsoft Learn, dynamic emergency calling","layout":"ladder","actors":["Teams client","LIS","Phone System","SBC or provider"],"chart":"none","icon":"emergency","keys":[["LIS","Network to address"],["Emergency address","Civic"],["PIDF-LO","Direct Routing option"],["Nomadic","Retest after roam"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"network","kind":"note","cap":"The client reports subnet, BSSID, or switch chassis and port."},{"f":1,"t":0,"label":"address","kind":"ok","cap":"LIS returns the emergency address for that network. A nomadic client on a new network does not keep the office address."},{"f":0,"t":2,"label":"911","kind":"req","cap":"Phone System places the emergency call."},{"f":2,"t":3,"label":"PIDF-LO","kind":"note","cap":"On Direct Routing, PIDF-LO is passed when the SBC is configured with PidfLoSupported and the trunk agrees. Calling Plan uses Microsoft's emergency path instead."}]},{"id":"e911-kari","title":"On-site notification","why":"Kari's Law requires notification to a person on site when 911 is dialed, without a prefix. The PSAP call and the security-desk call are two legs. Test both.","cite":"Kari's Law and Ray Baum's Act","layout":"ladder","actors":["Caller","PBX","PSAP","Security"],"chart":"none","icon":"emergency","keys":[["911","Emergency pattern"],["ELIN","Callback number"],["ERL","Emergency response location"],["Kari","On-site notification"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"911","kind":"req","cap":"The user dials 911, not 9-911, unless 911 itself is the pattern you built and tested."},{"f":1,"t":2,"label":"PSAP leg","kind":"req","cap":"One leg goes to the public safety answering point with a callback number and a dispatchable location."},{"f":1,"t":3,"label":"notify","kind":"note","cap":"A second action alerts on-site staff with the caller's location. If this leg fails, the PSAP call can still look fine."}]},{"id":"qos-path","title":"QoS marking path","why":"Mark voice bearer as EF, DSCP 46, as close to the phone as you trust. Re-mark at the WAN edge if the access layer is not trusted. A provider that remarks EF to best effort will show up as jitter, not as a link-down.","cite":"RFC 3246 and Cisco collaboration QoS","layout":"ladder","actors":["Phone","Access","WAN edge","Provider"],"chart":"qos","icon":"qos","keys":[["DSCP 46","EF bearer"],["DSCP 24","CS3 signaling, Cisco path"],["150 ms","G.114 one-way planning"],["< 1% loss","Design target, then measure"]],"header":null,"audio":true,"steps":[{"f":0,"t":1,"label":"DSCP 46","kind":"note","cap":"The phone marks RTP as EF. Signaling is commonly CS3, DSCP 24, on a Cisco collaboration design."},{"f":1,"t":2,"label":"trust","kind":"note","cap":"The access switch trusts the voice VLAN or re-marks. An untrusted port that keeps the phone's mark is a choice. An untrusted port that zeros it is a different choice."},{"f":2,"t":3,"label":"LLQ","kind":"note","cap":"The WAN edge puts EF in the priority queue. The priority class needs a policer so it cannot starve the link."},{"f":3,"t":3,"label":"remark","kind":"err","cap":"If the provider remarks EF to 0, your queuing no longer sees voice. Measure DSCP before and after the provider handoff."}]},{"id":"qos-trust","title":"Trust boundary","why":"Trust a mark only from a device you control. A PC on the voice VLAN can stamp EF on a backup job and starve the priority queue.","cite":"Cisco QoS SRND practice","layout":"ladder","actors":["Endpoint","Switch","Router"],"chart":"qos","icon":"qos","keys":[["DSCP 46","EF bearer"],["DSCP 24","CS3 signaling, Cisco path"],["150 ms","G.114 one-way planning"],["< 1% loss","Design target, then measure"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"mark","kind":"note","cap":"The phone marks on the voice VLAN. The PC port should be remarked to best effort or a scavenger class."},{"f":1,"t":2,"label":"trust","kind":"note","cap":"The uplink trusts the switch. The router classifies on DSCP."},{"f":2,"t":2,"label":"police","kind":"note","cap":"Police the priority class. A full EF queue that is mostly backups is a trust bug, not a need for a bigger queue."}]},{"id":"qos-wifi","title":"Wi-Fi voice","why":"Wi-Fi voice needs WMM access categories, not just a strong signal. Voice belongs in the voice queue. A sticky roam or a power-save client sounds like packet loss.","cite":"Wi-Fi multimedia, voice design","layout":"ladder","actors":["Phone","AP","Controller","WAN"],"chart":"mos","icon":"qos","keys":[["WMM","Voice AC"],["DSCP 46","On the wire"],["Roam","A loss burst"],["Power save","Gaps in RTP"]],"header":null,"audio":true,"steps":[{"f":0,"t":1,"label":"WMM","kind":"note","cap":"The client uses the voice access category. Without WMM, frames wait with bulk data."},{"f":1,"t":2,"label":"roam","kind":"note","cap":"A roam that takes too long drops RTP. Design the overlap and the fast-roam method."},{"f":2,"t":3,"label":"DSCP","kind":"note","cap":"The controller must map the WMM category back to DSCP 46 on the wired side, or the WAN will not see EF."}]},{"id":"qos-sdwan","title":"SD-WAN and voice","why":"An SD-WAN overlay can look up while it brownouts voice. The application policy has to match RTP, not only the SIP port, and the path must stay inside the delay budget.","cite":"SD-WAN voice policy","layout":"ladder","actors":["Branch","Overlay","Hub"],"chart":"qos","icon":"qos","keys":[["RTP","Classify media"],["EF","Still DSCP 46"],["Brownout","Up but lossy"],["150 ms","Budget the overlay"]],"header":null,"audio":true,"steps":[{"f":0,"t":1,"label":"classify","kind":"note","cap":"Match RTP, not only TCP 5061. Media is UDP and will miss a policy that names only SIP."},{"f":1,"t":1,"label":"path","kind":"note","cap":"The overlay picks a path. A lossy cheaper path is the wrong choice for EF even if the SLA color is green."},{"f":1,"t":2,"label":"deliver","kind":"media","cap":"Measure one-way delay, loss, and jitter on the overlay. Interface up is not the same as a usable voice path."}]},{"id":"ipv6-media","title":"One address family per media leg","why":"The SDP answer selects an address for that stream. An IPv4 c= line does not carry IPv6 RTP. A guest network that is IPv6-only will not reach an IPv4-only media server.","cite":"RFC 3264 and ICE","layout":"ladder","actors":["Offer","Answer","Media"],"chart":"none","icon":"route","keys":[["c=","Connection address"],["ICE pair","One family"],["IPv4-only","Cannot send IPv6"],["Silent 200","Often this"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"c=","kind":"req","cap":"The offer lists the addresses it can use. ICE may list both families as candidates."},{"f":1,"t":0,"label":"selected","kind":"ok","cap":"The answer or the nominated pair picks one. That pair is the media path."},{"f":0,"t":2,"label":"RTP","kind":"media","cap":"Packets use that family. If one side has no address in the chosen family, the call signals and stays silent."}]},{"id":"access-path","title":"Phone boot path","why":"A phone with no power, no VLAN, or no DHCP never reaches CUCM. Check those before you open a SIP trace.","cite":"Cisco IP phone boot","layout":"ladder","actors":["Switch","DHCP","TFTP","CUCM"],"chart":"none","icon":"phone","keys":[["PoE","Power first"],["Voice VLAN","CDP or LLDP"],["Option 150","TFTP"],["6970","Config files"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"PoE","kind":"note","cap":"The port must supply power or the phone needs a cube. No lights, no SIP."},{"f":0,"t":1,"label":"voice VLAN","kind":"note","cap":"The phone learns the voice VLAN from CDP or LLDP. A missing VLAN puts it on the data network or nowhere."},{"f":1,"t":2,"label":"options","kind":"note","cap":"DHCP gives an address, a gateway, and option 150 for TFTP."},{"f":2,"t":3,"label":"config","kind":"ok","cap":"The phone downloads its config and registers. Only then does dial tone mean the cluster."}]},{"id":"mig-dual-run","title":"Dual-run a number","why":"Dual-run means one number can be moved back by a routing change you already rehearsed. A canary cohort proves the new path before the rest of the site.","cite":"Migration practice","layout":"ladder","actors":["Carrier","Old","New","Canary"],"chart":"none","icon":"migration","keys":[["Canary","Small cohort"],["Two Call-IDs","Old and new"],["Rollback","A route, rehearsed"],["Evidence","Before the window"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"today","kind":"note","cap":"The number still completes on the old platform. Capture a Call-ID there."},{"f":0,"t":2,"label":"canary","kind":"req","cap":"Move a small cohort, not the executives first, by translation or by carrier routing."},{"f":2,"t":3,"label":"prove","kind":"ok","cap":"Place a test call. Save the new Call-ID, the media path, and the agent or user who answered."},{"f":0,"t":1,"label":"rollback","kind":"bye","cap":"Rollback is the route change in reverse. If you cannot say that sentence, you are not ready to cut."}]},{"id":"mig-port","title":"Number port","why":"A FOC date is a carrier event. Until the port completes, calls still hit the old carrier. After it completes, SMS and CNAM can lag. Test the voice path the hour of the port.","cite":"Local number portability","layout":"ladder","actors":["Old carrier","LNP","New carrier","PBX"],"chart":"none","icon":"migration","keys":[["FOC","The minute that matters"],["Control call","Before"],["Test call","After"],["CNAM","May lag"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"before","kind":"note","cap":"Calls complete on the old carrier. Record a control call."},{"f":1,"t":2,"label":"FOC","kind":"req","cap":"At the firm order commit, routing in the public network moves."},{"f":2,"t":3,"label":"deliver","kind":"ok","cap":"The new carrier delivers to your trunk. Your dial plan must already accept the number."},{"f":3,"t":3,"label":"after","kind":"note","cap":"Voice can work while caller ID name and messaging still show the old provider. Those are separate."}]},{"id":"mig-rollback","title":"Rollback drill","why":"A rollback you have not timed is a wish. Run it once with the same people who will be awake during the window.","cite":"Migration practice","layout":"ladder","actors":["Detect","Decide","Reverse","Prove"],"chart":"none","icon":"migration","keys":[["Trigger","Written down"],["Reverse","One change"],["Timer","How long it took"],["Control call","The proof"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"trigger","kind":"err","cap":"Name the metric that aborts the window: failure rate, no audio, emergency call fail."},{"f":1,"t":2,"label":"reverse","kind":"note","cap":"The reverse action is a route, a trunk, or a DNS target you can reach without a change ticket you do not have."},{"f":2,"t":3,"label":"prove","kind":"ok","cap":"The control call succeeds on the old path and you have its id."}]},{"id":"mig-trunk","title":"SIP trunk cutover","why":"Move the trunk only after a test number works on the new peer. Keep OPTIONS up on both peers until the cut is proven.","cite":"SIP trunk migration","layout":"ladder","actors":["CUCM","Old peer","New peer"],"chart":"none","icon":"cube","keys":[["Test pattern","First"],["OPTIONS","Both peers"],["Preference","The cut"],["Old peer","Stays until hypercare"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"steady","kind":"ok","cap":"Production uses the old dial-peer or route group."},{"f":0,"t":2,"label":"test","kind":"req","cap":"A test pattern uses the new peer. Compare SDP, codecs, and DTMF."},{"f":0,"t":2,"label":"cut","kind":"req","cap":"The production route list prefers the new peer."},{"f":0,"t":1,"label":"back","kind":"bye","cap":"The old peer stays built so preference can flip back."}]},{"id":"mig-upgrade","title":"CUCM upgrade path","why":"An upgrade from 12 to 14 or 15 is a maintenance window with a reboot and a database migration. Phones re-register. AXL clients break if they still speak the old schema.","cite":"Cisco Unified CM upgrade guide","layout":"ladder","actors":["Publisher","Subscribers","Phones","AXL clients"],"chart":"none","icon":"cert","keys":[["Backup","Before"],["Replication","After"],["Phones","Re-register"],["AXL schema","Update clients"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"backup","kind":"note","cap":"Take the backup and confirm you can read it before you start."},{"f":0,"t":1,"label":"switch","kind":"note","cap":"The publisher upgrades, then subscribers. Replication must catch up before you call it done."},{"f":1,"t":2,"label":"re-register","kind":"ok","cap":"Phones come back. A phone that does not is a firmware or a trust-list problem, not a dial-plan problem."},{"f":3,"t":0,"label":"AXL","kind":"err","cap":"Update AXL clients to the new schema. An old WSDL fails writes after the upgrade."}]},{"id":"mig-vm","title":"Voicemail move","why":"Move the mailbox and the message-waiting path together. A user who can leave a message on the new system and still lights the old lamp is half migrated.","cite":"Voicemail migration","layout":"ladder","actors":["CUCM","Old VM","New VM","Phone"],"chart":"none","icon":"phone","keys":[["Pilot","The forward target"],["MWI","Separate"],["Mailbox","Must exist first"],["Canary","A few users"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"today","kind":"note","cap":"The pilot points at the old system. MWI comes from there."},{"f":0,"t":2,"label":"pilot","kind":"req","cap":"Cut the pilot to the new system for the canary users."},{"f":2,"t":3,"label":"MWI","kind":"ok","cap":"Prove the lamp follows a new message and clears when the message is read."},{"f":0,"t":1,"label":"back","kind":"note","cap":"Rollback is the pilot and the MWI switch, both."}]},{"id":"mig-e911","title":"Emergency calling during a cut","why":"Do not cut a site until a test emergency call from that site reaches the right location and notifies on-site staff. A successful normal call does not prove this.","cite":"Kari's Law, Ray Baum's Act","layout":"ladder","actors":["Site","Old path","New path","Notify"],"chart":"none","icon":"emergency","keys":[["911","Emergency pattern"],["ELIN","Callback number"],["ERL","Emergency response location"],["Kari","On-site notification"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"baseline","kind":"note","cap":"You already know the old ELIN and the old notification target."},{"f":0,"t":2,"label":"test","kind":"req","cap":"Place the test call the way the carrier allows, from a phone on that floor."},{"f":2,"t":3,"label":"notify","kind":"ok","cap":"On-site notification fires with the right location."},{"f":0,"t":1,"label":"hold","kind":"err","cap":"If either leg fails, the site stays on the old emergency path."}]},{"id":"mig-sso","title":"Identity cutover","why":"An identity provider outage locks the desktop and leaves the phone registered. Test a call and a desktop login as separate proofs.","cite":"SSO and contact-center desktops","layout":"ladder","actors":["IdP","Desktop","Phone","Agent"],"chart":"none","icon":"cert","keys":[["IdP","Desktop"],["Phone","May stay up"],["Secret expiry","Alarm it"],["Ready state","The real test"]],"header":null,"audio":false,"steps":[{"f":0,"t":1,"label":"token","kind":"note","cap":"The agent desktop needs a token. The phone does not."},{"f":1,"t":3,"label":"login","kind":"ok","cap":"Login works and the agent can go ready."},{"f":2,"t":3,"label":"call","kind":"ok","cap":"A call still arrives if the IdP is down, or it does not, depending on the platform. Know which, and write it down."},{"f":0,"t":1,"label":"expiry","kind":"err","cap":"A certificate or a secret on the scheduled job expires quietly. Alarm on the date."}]},{"id":"qos-drop","title":"EF starvation","why":"If the priority queue is full of the wrong traffic, voice drops while the interface looks fine. Check who is marked EF before you buy bandwidth.","cite":"Cisco LLQ","layout":"ladder","actors":["Backup","Switch","Priority queue","Voice"],"chart":"qos","icon":"qos","keys":[["DSCP 46","EF bearer"],["DSCP 24","CS3 signaling, Cisco path"],["150 ms","G.114 one-way planning"],["< 1% loss","Design target, then measure"]],"header":null,"audio":true,"steps":[{"f":0,"t":1,"label":"marked EF","kind":"err","cap":"A bulk flow is marked DSCP 46 because a port trusts everything."},{"f":1,"t":2,"label":"police","kind":"note","cap":"The priority queue fills. The policer drops. Voice is in that queue too."},{"f":3,"t":2,"label":"loss","kind":"media","cap":"RTP loss rises. The interface is up. Jitter and drops are in the class, not in line protocol."},{"f":1,"t":1,"label":"fix","kind":"ok","cap":"Remark the access port. Voice stays EF. The backup does not."}]},{"id":"ts-one-way","title":"One-way audio","why":"One-way audio means signaling finished and one RTP direction did not. Start at SDP, then counters, then the filter in the middle.","cite":"RFC 3264 and RTP","layout":"tree","actors":["Check"],"chart":"mos","icon":"media","keys":[["RTP","Even UDP port, dynamic"],["RTCP","Usually RTP port + 1"],["16384\u201332767","Common Cisco range"],["SDP c= / m=","Where media is sent"]],"header":null,"audio":true,"steps":[{"f":0,"t":0,"label":"200 and ACK","kind":"note","cap":"Confirm both legs reached 200 OK and ACK. If ACK is missing, this is not one-way audio yet."},{"f":0,"t":0,"label":"SDP c= and m=","kind":"note","cap":"Compare address and port in each direction. A private c= line that nobody rewrote will fail one way."},{"f":0,"t":0,"label":"RTP counters","kind":"media","cap":"One side's packets-sent increases. The other side's packets-received does not. That names the dead direction."},{"f":0,"t":0,"label":"Middlebox","kind":"err","cap":"NAT, ACL, SIP ALG, or asymmetric routing sits on that direction. Change one of those."},{"f":0,"t":0,"label":"Recapture","kind":"ok","cap":"The same Call-ID should show both directions after the change."}]},{"id":"ts-ringback","title":"No ringback","why":"Missing ringback is either a missing 180, a 183 with no media, or a phone that was told not to play local ringback.","cite":"RFC 3960","layout":"tree","actors":["Check"],"chart":"none","icon":"media","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":true,"steps":[{"f":0,"t":0,"label":"Which 18x","kind":"note","cap":"180 without SDP means the caller should play local ringback. 183 with SDP means the network should play it."},{"f":0,"t":0,"label":"Early RTP","kind":"media","cap":"If you negotiated 183, capture RTP before 200 OK. Silence means the early stream is not arriving."},{"f":0,"t":0,"label":"Local ringback","kind":"note","cap":"If a 183 suppressed local ringback and then sent no audio, the caller hears nothing. That is a configuration pair, not a mystery."},{"f":0,"t":0,"label":"One change","kind":"ok","cap":"Either restore local ringback or fix the early-media path. Then place one call."}]},{"id":"ts-busy","title":"Fast busy or reorder","why":"Reorder means the switch or the trunk refused the call. Find the final SIP response or the ISDN cause before you touch QoS.","cite":"RFC 3261","layout":"tree","actors":["Check"],"chart":"sip","icon":"phone","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":true,"steps":[{"f":0,"t":0,"label":"Final response","kind":"err","cap":"404, 484, 486, 503, or an ISDN cause. Write the number down."},{"f":0,"t":0,"label":"Which hop","kind":"note","cap":"The Via or the trunk that generated it is the leg. A 503 from the carrier is not a CUCM CSS bug."},{"f":0,"t":0,"label":"Pattern","kind":"note","cap":"If CUCM generated a 404, digit analysis did not find a pattern in the CSS. That is a dial-plan fault."},{"f":0,"t":0,"label":"Prove","kind":"ok","cap":"After one change, the same digits should return 180 or 183 instead of that final error."}]},{"id":"ts-dead-air","title":"Dead air after answer","why":"The call was answered and neither side hears audio. Both RTP directions are missing or the bridge inserted itself and failed.","cite":"RTP","layout":"tree","actors":["Check"],"chart":"codec","icon":"media","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":true,"steps":[{"f":0,"t":0,"label":"Answered","kind":"ok","cap":"200 OK and ACK on the leg you own."},{"f":0,"t":0,"label":"Both counters","kind":"media","cap":"Packets sent and received on each hop. Dead air is both directions or a mixer that is silent."},{"f":0,"t":0,"label":"MTP or bridge","kind":"note","cap":"If SDP points at CUCM or a conference bridge, that resource must have a free port and a working codec."},{"f":0,"t":0,"label":"Codec","kind":"note","cap":"The payload in RTP must be the payload in the answer. A mismatch is silence, not noise."}]},{"id":"ts-dtmf","title":"DTMF not detected","why":"The digit method that left the phone is not the method the IVR is listening for. Name the method before you change codecs.","cite":"RFC 4733","layout":"tree","actors":["Check"],"chart":"none","icon":"media","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":true,"steps":[{"f":0,"t":0,"label":"Method","kind":"note","cap":"RFC 4733 events, SIP INFO, KPML, or in-band tones. The offer shows which one was agreed."},{"f":0,"t":0,"label":"Payload","kind":"note","cap":"Telephone-event must be in the answer. A transcoder that cannot pass events will eat them."},{"f":0,"t":0,"label":"One digit","kind":"media","cap":"Capture a single digit end to end. If it leaves the phone and never arrives, the SBC conversion is the leg."},{"f":0,"t":0,"label":"IVR log","kind":"ok","cap":"The IVR log for that contact id should show the digit after the fix."}]},{"id":"ts-fax","title":"Fax over IP failed","why":"T.38 and G.711 passthrough are different contracts. A SIP profile that strips the T.38 re-INVITE breaks fax and leaves voice working.","cite":"T.38 and T.30","layout":"tree","actors":["Check"],"chart":"none","icon":"media","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":true,"steps":[{"f":0,"t":0,"label":"Which mode","kind":"note","cap":"Confirm both sides agreed T.38 or both stayed on G.711. A mid-call re-INVITE switches to T.38."},{"f":0,"t":0,"label":"CNG and CED","kind":"media","cap":"1100 Hz calling tone and 2100 Hz answer tone should be visible if you are still in audio."},{"f":0,"t":0,"label":"Re-INVITE","kind":"req","cap":"If the re-INVITE is rejected, the profile or the peer refused T.38. Voice will still work."},{"f":0,"t":0,"label":"One page","kind":"ok","cap":"Send one page after a single change. A long document hides the result."}]},{"id":"ts-cert","title":"Certificate failure","why":"TLS fails before SIP. The name, the chain, or the date is wrong. A packet capture of the handshake tells you which.","cite":"TLS and SIP","layout":"tree","actors":["Check"],"chart":"none","icon":"cert","keys":[["Name","Must match"],["Chain","Intermediates"],["NTP","Not-before"],["5061","SIP TLS"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Name","kind":"note","cap":"The name in the certificate must match the name the client dialed."},{"f":0,"t":0,"label":"Chain","kind":"note","cap":"The server must send intermediates. A client that only has the root cannot build the chain."},{"f":0,"t":0,"label":"Clock","kind":"err","cap":"Not-before and not-after are absolute. NTP skew makes a good certificate look invalid."},{"f":0,"t":0,"label":"Then SIP","kind":"ok","cap":"Only after the handshake do you look at REGISTER or INVITE."}]},{"id":"ts-dns","title":"DNS and SRV","why":"A trunk that uses a name fails when that name fails. NXDOMAIN and a stale resolver look like a peer outage.","cite":"RFC 3263","layout":"tree","actors":["Check"],"chart":"none","icon":"route","keys":[["SRV","RFC 3263"],["A or AAAA","The address"],["NXDOMAIN","Name is gone"],["TTL","Stale cache"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Name","kind":"note","cap":"Write the exact FQDN the dial-peer or trunk uses."},{"f":0,"t":0,"label":"SRV then A","kind":"note","cap":"SIP locates a service with SRV, then an address. A missing SRV and a present A record are different faults."},{"f":0,"t":0,"label":"Which resolver","kind":"note","cap":"The gateway's resolver, not your laptop. Query from the box that places the call."},{"f":0,"t":0,"label":"Failover","kind":"ok","cap":"A second SRV target should be used only after the first is actually unreachable."}]},{"id":"ts-repl","title":"Database replication","why":"A change on the publisher that a subscriber has not learned yet looks like a partition the phone cannot see. Check replication before you rebuild the CSS.","cite":"Cisco Unified CM","layout":"tree","actors":["Check"],"chart":"none","icon":"cert","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Where saved","kind":"note","cap":"Confirm the pattern exists on the publisher."},{"f":0,"t":0,"label":"Runtime state","kind":"note","cap":"utils dbreplication runtimestate shows who is behind."},{"f":0,"t":0,"label":"Which node","kind":"note","cap":"The phone is registered to a specific subscriber. That node must have the row."},{"f":0,"t":0,"label":"Retest","kind":"ok","cap":"After replication catches up, reset one phone and place one call."}]},{"id":"ts-echo","title":"Echo","why":"Echo is a reflection with delay. Gateways cancel it on TDM legs. A pure IP call that echoes is usually a device playing speaker into mic, not a QoS queue.","cite":"Voice quality","layout":"tree","actors":["Check"],"chart":"mos","icon":"media","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":true,"steps":[{"f":0,"t":0,"label":"Which leg","kind":"note","cap":"IP to IP, or IP to TDM. The canceler lives on the TDM gateway."},{"f":0,"t":0,"label":"Delay","kind":"note","cap":"Echo that is almost immediate is local. Echo after a beat is the far end coming back."},{"f":0,"t":0,"label":"Canceler","kind":"note","cap":"Confirm the echo canceler is on and covering the tail length you actually have."},{"f":0,"t":0,"label":"One call","kind":"ok","cap":"Retest the same path. A different path is a different fault."}]},{"id":"ts-jitter","title":"Jitter","why":"Jitter is delay variation. The jitter buffer hides a little of it and adds delay. When it underruns, you hear gaps. The queue that caused it is upstream of the phone.","cite":"ITU-T G.114 and RTP","layout":"tree","actors":["Check"],"chart":"mos","icon":"qos","keys":[["DSCP 46","EF bearer"],["DSCP 24","CS3 signaling, Cisco path"],["150 ms","G.114 one-way planning"],["< 1% loss","Design target, then measure"]],"header":null,"audio":true,"steps":[{"f":0,"t":0,"label":"Where","kind":"note","cap":"RTCP or the phone stats name the direction and the size."},{"f":0,"t":0,"label":"Queue","kind":"note","cap":"Look at the WAN class. A burst in the priority queue or a remarked DSCP matches the time of the complaint."},{"f":0,"t":0,"label":"Buffer","kind":"note","cap":"A deeper jitter buffer trades delay for fewer gaps. It does not fix a saturated link."},{"f":0,"t":0,"label":"Measure again","kind":"ok","cap":"The same call path should show a smaller jitter figure after one change."}]},{"id":"ts-loss","title":"Packet loss","why":"Loss is missing RTP sequence numbers. A policer, a bad Wi-Fi roam, or a full queue does this. The SIP ladder will look clean.","cite":"RFC 3550","layout":"tree","actors":["Check"],"chart":"mos","icon":"qos","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":true,"steps":[{"f":0,"t":0,"label":"Sequence","kind":"media","cap":"Gaps in RTP sequence numbers are loss. Reordering is a different pattern."},{"f":0,"t":0,"label":"Which hop","kind":"note","cap":"Compare counters on the phone and on the SBC. The hop where received stops growing is the leg."},{"f":0,"t":0,"label":"Class","kind":"note","cap":"Drops in the LLQ class, Wi-Fi retries, or an overlay brownout. Interface up is not evidence."},{"f":0,"t":0,"label":"Retest","kind":"ok","cap":"One call, same codec, loss back under the design target."}]},{"id":"ts-mos","title":"MOS fell","why":"MOS is an outcome. Codec, loss, and delay are the causes. Change one cause and read MOS again. Do not average it with a different path.","cite":"ITU-T G.107 teaching model","layout":"tree","actors":["Check"],"chart":"mos","icon":"qos","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":true,"steps":[{"f":0,"t":0,"label":"Codec","kind":"note","cap":"G.711 and G.729 do not share an impairment. Know which payload was answered."},{"f":0,"t":0,"label":"Loss and delay","kind":"note","cap":"Read them from RTCP or the endpoint, not from a WAN average."},{"f":0,"t":0,"label":"One variable","kind":"note","cap":"Change codec or fix loss, not both, or you will not know which helped."},{"f":0,"t":0,"label":"Same path","kind":"ok","cap":"Repeat the call on the same two endpoints."}]},{"id":"ts-refer","title":"REFER failed","why":"202 Accepted only means the transfer was requested. NOTIFY carries the result. A failed INVITE to the target is the actual fault.","cite":"RFC 3515","layout":"tree","actors":["Check"],"chart":"none","icon":"sip","keys":[["202","Accepted"],["NOTIFY","Result"],["New Call-ID","The target leg"],["Replaces","Attended"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"202","kind":"ok","cap":"The REFER was accepted. Keep looking."},{"f":0,"t":0,"label":"NOTIFY","kind":"note","cap":"The sipfrag status is the result of the new INVITE."},{"f":0,"t":0,"label":"Target","kind":"err","cap":"The new INVITE has its own Call-ID. That ladder is the one that failed."},{"f":0,"t":0,"label":"Replaces","kind":"note","cap":"Attended transfer adds Replaces. A target that ignores Replaces rings a second time or rejects the call."}]},{"id":"ts-alg","title":"SIP ALG rewrote SDP","why":"A firewall SIP ALG rewrites SDP with a second opinion. Turn it off and let the SBC own the rewrite. Two rewrites produce one-way audio.","cite":"SDP c=","layout":"tree","actors":["Check"],"chart":"none","icon":"route","keys":[["RTP","Even UDP port, dynamic"],["RTCP","Usually RTP port + 1"],["16384\u201332767","Common Cisco range"],["SDP c= / m=","Where media is sent"]],"header":null,"audio":true,"steps":[{"f":0,"t":0,"label":"Compare c=","kind":"note","cap":"Capture in front of the firewall and behind it. If c= changed twice, an ALG is in the path."},{"f":0,"t":0,"label":"Disable ALG","kind":"note","cap":"The SBC already rewrites SDP for the outside."},{"f":0,"t":0,"label":"One call","kind":"media","cap":"RTP should arrive at the address the SBC wrote."},{"f":0,"t":0,"label":"Leave it off","kind":"ok","cap":"Document the ALG change so the next firewall refresh does not turn it back on."}]},{"id":"ts-srtp","title":"SRTP mismatch","why":"A call that negotiates RTP/AVP on one leg and RTP/SAVP on the other needs a translator or it stays silent. Optional SRTP that falls back will look like a policy bug.","cite":"RFC 3711","layout":"tree","actors":["Check"],"chart":"none","icon":"cert","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":true,"steps":[{"f":0,"t":0,"label":"Profile","kind":"note","cap":"Read m= on both legs. SAVP and AVP are not interchangeable."},{"f":0,"t":0,"label":"Crypto","kind":"note","cap":"a=crypto suites must overlap for SDES. DTLS-SRTP uses a fingerprint instead."},{"f":0,"t":0,"label":"Fallback","kind":"err","cap":"If the policy says SRTP required and the peer falls back to RTP, the call should fail, not quietly downgrade."},{"f":0,"t":0,"label":"Retest","kind":"ok","cap":"Both legs show the same profile and decoded audio."}]},{"id":"ts-ghost","title":"Ghost INVITEs","why":"INVITEs you did not place are scans, loops, or a device retrying a failed call. The source and the Request-URI tell you which.","cite":"RFC 3261","layout":"tree","actors":["Check"],"chart":"none","icon":"sip","keys":[["Request-URI","Who they asked for"],["Via","Who sent it"],["Loop","A forward"],["Admit","SBC list"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Source","kind":"note","cap":"The Via and the real socket address. Spoofed UDP is possible. TLS is harder to spoof."},{"f":0,"t":0,"label":"Request-URI","kind":"note","cap":"A scan walks extensions. A loop repeats one number with climbing CSeq or a new Call-ID each time."},{"f":0,"t":0,"label":"Loop","kind":"err","cap":"A forward or a translation that returns to itself. Break the forward."},{"f":0,"t":0,"label":"Edge","kind":"ok","cap":"An SBC admit list drops the rest. Do not only block on CUCM."}]},{"id":"ts-toll","title":"Toll fraud","why":"A catch-all pattern plus a trunk is a billing event. Close the pattern, then look for the calls that already left.","cite":"Dial-plan security","layout":"tree","actors":["Check"],"chart":"none","icon":"emergency","keys":[["Pattern","What matched"],["CSS","Who can dial it"],["CDR","What already left"],["Trunk","The exit"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Pattern","kind":"err","cap":"Find the route pattern that matched. A trailing dot that is too wide is the usual hole."},{"f":0,"t":0,"label":"CSS","kind":"note","cap":"Who can reach that pattern: a phone, a trunk, a voicemail port, a conference."},{"f":0,"t":0,"label":"CDR","kind":"note","cap":"Call detail for the window: calling number, called number, duration, trunk."},{"f":0,"t":0,"label":"Close","kind":"ok","cap":"Restrict the pattern and place a test call that must now fail."}]},{"id":"ts-rec","title":"Recording did not resume","why":"A compliance pause that never resumes is a stuck flag, not a missing recorder. The call id should show pause and resume as two events.","cite":"SIPREC, RFC 7866, and contact-center recording","layout":"tree","actors":["Check"],"chart":"none","icon":"proof","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Pause event","kind":"note","cap":"The desktop or the SIPREC session shows pause at a time."},{"f":0,"t":0,"label":"Resume","kind":"err","cap":"There should be a resume when the payment segment ends. If the event never left the desktop, the recorder is innocent."},{"f":0,"t":0,"label":"Media","kind":"media","cap":"After resume, the forked stream should contain audio again."},{"f":0,"t":0,"label":"One call","kind":"ok","cap":"A test call that pauses and resumes, with both timestamps."}]},{"id":"ts-mra","title":"MRA certificate chain","why":"Expressway-E must send the intermediate certificates. Clients fail the TLS handshake and never send REGISTER.","cite":"Cisco Expressway MRA","layout":"tree","actors":["Check"],"chart":"none","icon":"cert","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Name","kind":"note","cap":"The public name on the certificate matches the service discovery name."},{"f":0,"t":0,"label":"Chain","kind":"err","cap":"Capture the handshake. If the intermediate is missing, the client cannot build a path to a root it trusts."},{"f":0,"t":0,"label":"Zones","kind":"note","cap":"Traversal zones E and C are a later check. They do not matter until TLS succeeds."},{"f":0,"t":0,"label":"REGISTER","kind":"ok","cap":"One client registers and places one on-net call."}]},{"id":"ts-ha","title":"SBC high-availability split brain","why":"Two active SBCs own the same virtual address. Neighbors flap and calls land on a box that does not have the dialog.","cite":"CUBE high availability","layout":"tree","actors":["Check"],"chart":"none","icon":"cube","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Who is active","kind":"err","cap":"Both boxes claim active. The redundancy group heartbeat is down or the WAN between them is split."},{"f":0,"t":0,"label":"VIP","kind":"note","cap":"Neighbors ARP the virtual address and get two answers."},{"f":0,"t":0,"label":"Heartbeat","kind":"note","cap":"Restore the link used for the redundancy group before you move traffic."},{"f":0,"t":0,"label":"One active","kind":"ok","cap":"One box owns the VIP. A new test call completes and a checkpointed call still exists."}]},{"id":"ts-queue","title":"Queue starvation","why":"Agents are idle in one queue while another queue never reaches them. Skill assignment, priority, or an omnichannel flood is holding the pool.","cite":"Contact-center routing","layout":"tree","actors":["Check"],"chart":"kpi","icon":"queue","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Which queue","kind":"note","cap":"The contact's queue and priority, from the contact id."},{"f":0,"t":0,"label":"Who is ready","kind":"note","cap":"Agents who can take that queue and are actually ready, not just logged in."},{"f":0,"t":0,"label":"What they took instead","kind":"err","cap":"A higher-priority queue or a digital channel consumed them."},{"f":0,"t":0,"label":"One change","kind":"ok","cap":"Priority or staffing. The next interval should show offers to the starved queue."}]},{"id":"ts-loc","title":"Emergency location mismatch","why":"The call completed and the location was wrong. That is a failed emergency test even though someone answered.","cite":"Ray Baum's Act","layout":"tree","actors":["Check"],"chart":"none","icon":"emergency","keys":[["911","Emergency pattern"],["ELIN","Callback number"],["ERL","Emergency response location"],["Kari","On-site notification"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Where from","kind":"note","cap":"The switch port, BSSID, or subnet the client actually used."},{"f":0,"t":0,"label":"What mapped","kind":"err","cap":"The ERL, emergency address, or HELD result for that network id."},{"f":0,"t":0,"label":"What the PSAP got","kind":"note","cap":"The callback number and the location delivered, plus whether on-site notification fired."},{"f":0,"t":0,"label":"Fix the map","kind":"ok","cap":"Correct one network id. Retest from that floor, not from a lab bench."}]},{"id":"ts-ntp","title":"Clock skew","why":"Certificates, CDRs, and logs lie when the clock steps. Fix NTP before you chase a storm of not-yet-valid errors.","cite":"NTP and TLS","layout":"tree","actors":["Check"],"chart":"none","icon":"cert","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Offset","kind":"err","cap":"Read the offset on the host that failed, not on your laptop."},{"f":0,"t":0,"label":"Step","kind":"note","cap":"A step backward makes certificates look not-yet-valid and reorders logs."},{"f":0,"t":0,"label":"Source","kind":"note","cap":"One source, reachable, not a peer that is itself unsynchronized."},{"f":0,"t":0,"label":"Retest TLS","kind":"ok","cap":"The handshake succeeds and the log timestamps match the call."}]},{"id":"ts-oauth","title":"Token expiry","why":"A desktop or a scheduled job fails when the secret expires. Calls that do not need that token keep working, which hides the fault.","cite":"OAuth","layout":"tree","actors":["Check"],"chart":"none","icon":"cert","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Which token","kind":"note","cap":"User login, app registration, or a job secret. They expire on different dates."},{"f":0,"t":0,"label":"Symptom","kind":"err","cap":"401 or an interactive login loop. Not a SIP 407 unless you are looking at a SIP challenge."},{"f":0,"t":0,"label":"Renew","kind":"note","cap":"Renew and store the date where someone will see it."},{"f":0,"t":0,"label":"Prove","kind":"ok","cap":"The same user or job succeeds, and a phone call still works."}]},{"id":"ts-license","title":"License exhaustion","why":"A license or a session license that runs out fails the next call or the next agent login. Existing calls often stay up.","cite":"Capacity","layout":"tree","actors":["Check"],"chart":"erlang","icon":"proof","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Counter","kind":"err","cap":"The license or session counter at the time of the failure."},{"f":0,"t":0,"label":"Who needs one","kind":"note","cap":"Agent login, trunk session, MTP, or recording port. Name which counter hit the cap."},{"f":0,"t":0,"label":"Free one","kind":"note","cap":"A controlled release or an added license. Do not restart the cluster as the first move."},{"f":0,"t":0,"label":"Next call","kind":"ok","cap":"A new call or login succeeds and the counter is under the cap."}]},{"id":"ts-tftp","title":"Phone did not get its config","why":"Registration never starts if the file does not download. DHCP option 150 and HTTP 6970 are the usual CUCM path.","cite":"Cisco phone boot","layout":"tree","actors":["Check"],"chart":"none","icon":"phone","keys":[["Option 150","TFTP server"],["6970","HTTP config"],["File name","SEP plus MAC"],["REGISTER","Only after the file"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"IP","kind":"note","cap":"The phone has an address in the voice VLAN."},{"f":0,"t":0,"label":"Option 150","kind":"note","cap":"It points at a CUCM node that is actually up."},{"f":0,"t":0,"label":"File","kind":"err","cap":"The phone requests its config. A 404 means the name is wrong or the phone was never inserted."},{"f":0,"t":0,"label":"REGISTER","kind":"ok","cap":"After the file, REGISTER gets a 200."}]},{"id":"ts-pri","title":"PRI or T1 down","why":"A red alarm or a D-channel down is a circuit fault. SIP will not ring a gateway that has no B-channels.","cite":"ISDN PRI","layout":"tree","actors":["Check"],"chart":"none","icon":"route","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Alarm","kind":"err","cap":"LOS, LOF, AIS, or a D-channel down. Read it on the gateway."},{"f":0,"t":0,"label":"Channels","kind":"note","cap":"Busy-out versus a true outage. A full PRI returns a cause. A dead PRI does not answer."},{"f":0,"t":0,"label":"One call","kind":"note","cap":"Place a call and capture the ISDN cause if signaling is up."},{"f":0,"t":0,"label":"Carrier","kind":"ok","cap":"The loop or the channel is clean and a test call completes."}]},{"id":"ts-cpu","title":"CUCM CPU spike","why":"A node at high CPU delays SIP and skin updates. Find the process before you reboot. A reboot hides the evidence.","cite":"Cisco Unified CM","layout":"tree","actors":["Check"],"chart":"none","icon":"cert","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Which node","kind":"note","cap":"The subscriber the phones are registered to, or the publisher."},{"f":0,"t":0,"label":"Process","kind":"err","cap":"The process using the CPU. A trace level left at debug is a common cause."},{"f":0,"t":0,"label":"Scope","kind":"note","cap":"Lower the trace or stop the job. Do not change the dial plan in the same minute."},{"f":0,"t":0,"label":"Stable","kind":"ok","cap":"CPU falls and a test call completes on that node."}]},{"id":"ts-hunt-loop","title":"Hunt loop","why":"A member that forwards back to the pilot will ring until a counter saves you. Point the final forward outside the hunt.","cite":"Cisco hunt lists","layout":"tree","actors":["Check"],"chart":"none","icon":"queue","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Pilot","kind":"note","cap":"The number that was dialed."},{"f":0,"t":0,"label":"Member forward","kind":"err","cap":"The member's CFA or CFNA target. If it is the pilot, you have the loop."},{"f":0,"t":0,"label":"Final","kind":"note","cap":"Set a final destination that is not in the line group."},{"f":0,"t":0,"label":"One call","kind":"ok","cap":"RNA lands on the final destination once."}]},{"id":"ts-midcall","title":"Mid-call drop","why":"A call that dies after answer lost a re-INVITE, a timer, or a failover that was not checkpointed. The BYE or the timeout names which.","cite":"RFC 3261","layout":"tree","actors":["Check"],"chart":"sip","icon":"sip","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Who sent BYE","kind":"note","cap":"A BYE is a decision. A timeout is a dead peer or a failed re-INVITE."},{"f":0,"t":0,"label":"re-INVITE","kind":"err","cap":"Hold, codec change, or transfer. A rejected re-INVITE can drop the call if the peer treats it as fatal."},{"f":0,"t":0,"label":"Session timer","kind":"note","cap":"A session refresh that gets no answer will clear the dialog."},{"f":0,"t":0,"label":"One scenario","kind":"ok","cap":"Repeat the same hold or transfer. The dialog stays up."}]},{"id":"ts-setup-delay","title":"Slow call setup","why":"Delay before ring is digit analysis, DNS, a hunting trunk, or a remote proxy. It is not jitter. Jitter happens after audio starts.","cite":"RFC 3261","layout":"tree","actors":["Check"],"chart":"sip","icon":"sip","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Timestamp","kind":"note","cap":"INVITE to first 18x. That interval is the setup delay."},{"f":0,"t":0,"label":"Where it waited","kind":"note","cap":"Inter-digit timeout, SRV lookup, or a peer that never sent 100 Trying."},{"f":0,"t":0,"label":"100 Trying","kind":"prov","cap":"If your side never sent or received 100, the INVITE is retransmitting and the user waits."},{"f":0,"t":0,"label":"One hop","kind":"ok","cap":"Fix the hop that owned the gap. Measure the same interval again."}]},{"id":"ts-rona","title":"Agent RONA loop","why":"The agent is offered and does not answer, often because the headset slept. The contact returns to queue and the same agent is offered again if state did not change.","cite":"Contact center","layout":"tree","actors":["Check"],"chart":"kpi","icon":"queue","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Offer","kind":"note","cap":"The contact id shows an offer to a named agent."},{"f":0,"t":0,"label":"State","kind":"err","cap":"After RONA the agent should leave ready. If they stay ready, the loop is in the platform setting or the USB headset never answered."},{"f":0,"t":0,"label":"Headset","kind":"note","cap":"A USB power-save device that does not pick up is a RONA factory."},{"f":0,"t":0,"label":"Next offer","kind":"ok","cap":"The next offer goes to a different ready agent."}]},{"id":"ts-sso","title":"Desktop SSO only","why":"The identity provider is down. Phones still work. Agents cannot go ready. Treat the desktop and the call path as two systems.","cite":"SSO","layout":"tree","actors":["Check"],"chart":"none","icon":"cert","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Phone","kind":"ok","cap":"A registered phone can still call. Prove it so you do not restart CUCM."},{"f":0,"t":0,"label":"Desktop","kind":"err","cap":"The login page or the token endpoint fails."},{"f":0,"t":0,"label":"IdP","kind":"note","cap":"Status of the identity provider and the certificate it presents."},{"f":0,"t":0,"label":"Ready","kind":"ok","cap":"After the IdP returns, one agent goes ready and receives a queued contact."}]},{"id":"ts-dst","title":"Schedule and time zone","why":"A holiday or a daylight-saving boundary evaluated in the wrong zone sends callers to closed, or keeps them in open. The flow is doing what the clock told it.","cite":"Contact-center schedules","layout":"tree","actors":["Check"],"chart":"none","icon":"queue","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Zone","kind":"note","cap":"The zone on the schedule, not the zone on your laptop."},{"f":0,"t":0,"label":"Boundary","kind":"err","cap":"The hour the complaint started. DST and holiday eves live here."},{"f":0,"t":0,"label":"Branch","kind":"note","cap":"The flow took the closed or the open branch. The log shows which."},{"f":0,"t":0,"label":"Retest","kind":"ok","cap":"A test at that wall-clock time takes the branch you wanted."}]},{"id":"ts-lgw","title":"Local Gateway media blackhole","why":"Webex Calling registration or TLS is up and RTP is not. Signaling TCP can be fine while UDP media is filtered.","cite":"Webex Calling Local Gateway","layout":"tree","actors":["Check"],"chart":"codec","icon":"cloud","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":true,"steps":[{"f":0,"t":0,"label":"TLS","kind":"ok","cap":"The trunk is established. Certificate or registration is not the current fault."},{"f":0,"t":0,"label":"SDP","kind":"note","cap":"The addresses in SDP are the ones you meant: the gateway's outside address and the Webex media address."},{"f":0,"t":0,"label":"UDP","kind":"err","cap":"Media is UDP. A firewall that allows the SIP port and denies the media range produces this exact symptom."},{"f":0,"t":0,"label":"Both ways","kind":"ok","cap":"RTP counters increase in both directions on one test call."}]},{"id":"ts-bypass","title":"Media bypass blocked","why":"Teams signaling works and direct media does not. The firewall or a new zone blocks the bypass range, so the call must use the media processor or it stays silent.","cite":"Microsoft media bypass","layout":"tree","actors":["Check"],"chart":"mos","icon":"team","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":true,"steps":[{"f":0,"t":0,"label":"Bypass flag","kind":"note","cap":"The SBC is set for media bypass and the user is in scope."},{"f":0,"t":0,"label":"Path","kind":"err","cap":"Client to SBC UDP is blocked. The processor path may also be blocked if someone locked the zone too tightly."},{"f":0,"t":0,"label":"One path","kind":"note","cap":"Open the path you intend to use. Do not open every UDP port as the experiment."},{"f":0,"t":0,"label":"Audio","kind":"ok","cap":"A bypass user and a non-bypass user both have two-way audio, on purpose."}]},{"id":"ts-stir","title":"STIR verification failed","why":"Verification fails when the signed identity and the delivered calling number disagree. An SBC that strips PAI and keeps Identity will do this.","cite":"RFC 8224","layout":"tree","actors":["Check"],"chart":"none","icon":"cert","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Identity present","kind":"note","cap":"The header arrived at the verifier. If it did not, transit stripped it."},{"f":0,"t":0,"label":"Calling number","kind":"err","cap":"The number in the token and the number in From or PAI must match what the signer covered."},{"f":0,"t":0,"label":"Clock","kind":"note","cap":"The token date is checked. Skew fails good signatures."},{"f":0,"t":0,"label":"One call","kind":"ok","cap":"A signed test call verifies after the header policy is corrected."}]},{"id":"ts-turn","title":"Home agent needs TURN","why":"The browser cannot punch a direct media path through CGNAT or a SASE client. TURN relays it. If the relay is full, the agent is silent with a healthy SIP leg.","cite":"RFC 8656","layout":"tree","actors":["Check"],"chart":"mos","icon":"media","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":true,"steps":[{"f":0,"t":0,"label":"ICE result","kind":"note","cap":"The selected candidate is relay, or there is no selected pair."},{"f":0,"t":0,"label":"Capacity","kind":"err","cap":"TURN allocations at that moment. A full relay fails new agents and leaves old ones up."},{"f":0,"t":0,"label":"SASE","kind":"note","cap":"A client that hairpins into a cloud firewall changes the candidate set. Include it in the test."},{"f":0,"t":0,"label":"Audio","kind":"ok","cap":"The agent hears the caller and the allocation count is under the cap."}]},{"id":"ts-codec","title":"Codec mismatch","why":"The answer selected a payload the sender is not using, or a transcoder was required and none was free.","cite":"RFC 3264","layout":"tree","actors":["Check"],"chart":"codec","icon":"media","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":true,"steps":[{"f":0,"t":0,"label":"Offer","kind":"note","cap":"Payloads offered."},{"f":0,"t":0,"label":"Answer","kind":"ok","cap":"The single payload answered."},{"f":0,"t":0,"label":"On the wire","kind":"err","cap":"The RTP payload type actually sent. If it is not the answer, that side is wrong."},{"f":0,"t":0,"label":"Transcoder","kind":"note","cap":"If the two legs legally differ, a transcoder in the MRGL must have a session left."}]},{"id":"ts-park","title":"Call park failed","why":"Park is a hold against a slot number. If the slot is full or the retrieval CSS cannot see it, the call looks dropped.","cite":"Cisco call park","layout":"tree","actors":["Check"],"chart":"none","icon":"phone","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Park","kind":"note","cap":"The call left the phone and should be on a park number."},{"f":0,"t":0,"label":"Slot","kind":"err","cap":"The park range is exhausted, or the retrieval partition is not in the CSS."},{"f":0,"t":0,"label":"Retrieve","kind":"req","cap":"Dial the park number from a phone whose CSS includes that partition."},{"f":0,"t":0,"label":"Back","kind":"ok","cap":"The original caller is still there and audio returns."}]},{"id":"ts-presence","title":"Presence state","why":"Presence is a separate subscription from the call. A call can work while the lamp is wrong. The subscription id is the thing to capture.","cite":"SIP presence and CUCM","layout":"tree","actors":["Check"],"chart":"none","icon":"phone","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Call","kind":"ok","cap":"Confirm the call itself is fine so you do not debug RTP."},{"f":0,"t":0,"label":"State","kind":"err","cap":"The published state and the state the watcher shows. They differ at a specific hop."},{"f":0,"t":0,"label":"Subscribe","kind":"note","cap":"The watcher has to be allowed to subscribe. A privacy or CSS rule blocks the lamp and not the call."},{"f":0,"t":0,"label":"One watcher","kind":"ok","cap":"After one policy change, that watcher sees the new state."}]},{"id":"ts-rate","title":"API rate limit","why":"A 429 or a retry storm is the platform protecting itself. The contact may still be up. Stop the retry before you scale the dependency.","cite":"HTTP APIs","layout":"tree","actors":["Check"],"chart":"none","icon":"cloud","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Status","kind":"err","cap":"429, a vendor throttle, or a timeout. Read the body. It names the limit."},{"f":0,"t":0,"label":"Who retries","kind":"note","cap":"A webhook, a Lambda, or a screen-pop client. Retries multiply the load."},{"f":0,"t":0,"label":"Back off","kind":"note","cap":"Honor Retry-After. A tight loop is how Monday morning freezes a CRM."},{"f":0,"t":0,"label":"One contact","kind":"ok","cap":"A single test contact completes and the error rate falls."}]},{"id":"ts-scim","title":"SCIM left a zombie","why":"A partial delete removes the directory user and leaves the agent still routable. The contact center id and the directory id have to be compared.","cite":"SCIM provisioning","layout":"tree","actors":["Check"],"chart":"none","icon":"cert","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Directory","kind":"note","cap":"The user is gone or disabled in the identity store."},{"f":0,"t":0,"label":"Agent","kind":"err","cap":"The agent record still exists and can be set ready."},{"f":0,"t":0,"label":"Join","kind":"note","cap":"The SCIM id and the agent id. The delete event did not reach the second system."},{"f":0,"t":0,"label":"Disable","kind":"ok","cap":"The agent cannot go ready, and a new contact is not offered to them."}]},{"id":"ts-report-join","title":"Report join broke","why":"Renaming a skill changes the key historical reports join on. Live calls can be fine while yesterday's report splits in two.","cite":"Contact-center reporting","layout":"tree","actors":["Check"],"chart":"kpi","icon":"proof","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Live","kind":"ok","cap":"A call still queues and delivers. This is not an audio fault."},{"f":0,"t":0,"label":"Key","kind":"err","cap":"The report joins on a name that changed. Old rows use the old name."},{"f":0,"t":0,"label":"Map","kind":"note","cap":"Keep a map from the old key to the new key, or freeze the name."},{"f":0,"t":0,"label":"Interval","kind":"ok","cap":"One interval after the change shows a single queue, not two."}]},{"id":"ts-licc","title":"LICC on this fault","why":"Name the leg, copy the identifier, read the counter, take one capture. Then change one thing.","cite":"Campus method","layout":"tree","actors":["Check"],"chart":"none","icon":"proof","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Leg","kind":"note","cap":"The hop that failed, in one sentence from this section's title."},{"f":0,"t":0,"label":"Identifier","kind":"note","cap":"Call-ID, ContactId, conversation id, or RouterCallKey."},{"f":0,"t":0,"label":"Counter","kind":"note","cap":"The counter that should have moved and did not, or moved the wrong way."},{"f":0,"t":0,"label":"Capture","kind":"ok","cap":"One ladder, one RTP sample, or one report interval. Then a single change."}]},{"id":"evidence-pack","title":"Evidence pack","why":"A pack someone else can read beats a verbal recap. The claim, the id, and the capture belong together.","cite":"Campus method","layout":"tree","actors":["Check"],"chart":"none","icon":"proof","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Claim","kind":"note","cap":"One sentence: what failed, for whom, since when."},{"f":0,"t":0,"label":"Leg","kind":"note","cap":"The hop you believe failed."},{"f":0,"t":0,"label":"Identifier","kind":"note","cap":"The id that joins the systems."},{"f":0,"t":0,"label":"Capture","kind":"ok","cap":"The file, the report interval, or the command output. Link the vendor document you would re-check."}]},{"id":"design-read","title":"Read a design","why":"A design is a set of failure domains, a capacity unit, and an identity boundary. If those three are missing, the drawing is decoration.","cite":"Design practice","layout":"tree","actors":["Check"],"chart":"erlang","icon":"route","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Failure domain","kind":"note","cap":"What dies together: a node, a site, a trunk, an identity provider."},{"f":0,"t":0,"label":"Capacity","kind":"note","cap":"The unit: erlangs, agents, sessions, or trunks, with the formula you would use."},{"f":0,"t":0,"label":"Identity","kind":"note","cap":"Who authenticates, and what still works when that system does not."},{"f":0,"t":0,"label":"Proof","kind":"ok","cap":"The test call or the report that would show the design is still true."}]},{"id":"practice-loop","title":"Drill loop","why":"Answer from memory, then check the ladder, then write the miss as a new check. A drill you did not score did not happen.","cite":"Campus practice","layout":"tree","actors":["Check"],"chart":"none","icon":"proof","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Closed book","kind":"note","cap":"Say the leg and the identifier before you open the notes."},{"f":0,"t":0,"label":"Compare","kind":"note","cap":"Open the matching flow and mark what you skipped."},{"f":0,"t":0,"label":"Write the miss","kind":"note","cap":"One line you will look for next time."},{"f":0,"t":0,"label":"One more","kind":"ok","cap":"A second question on the same miss. Then stop."}]},{"id":"reference-loop","title":"Use a source","why":"Names drift. The glossary in this campus is a start. The vendor's current document is the one you cite before a change.","cite":"Vendor documentation","layout":"tree","actors":["Check"],"chart":"none","icon":"cert","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Term","kind":"note","cap":"The product's word, not a nickname."},{"f":0,"t":0,"label":"Document","kind":"note","cap":"The current guide for that version, not a blog from a different release."},{"f":0,"t":0,"label":"What you will re-check","kind":"note","cap":"One behavior: a port, a timer, a header."},{"f":0,"t":0,"label":"Then the lab","kind":"ok","cap":"Confirm it on a non-production call if you can."}]},{"id":"licc-path","title":"LICC","why":"Leg, identifier, counter, capture. This is the habit that keeps a bridge honest.","cite":"Campus method","layout":"tree","actors":["Check"],"chart":"none","icon":"proof","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Leg","kind":"note","cap":"Which hop failed. Phone, CUCM, CUBE, carrier, flow, or agent."},{"f":0,"t":0,"label":"Identifier","kind":"note","cap":"Call-ID, RouterCallKey, ContactId, or conversation id."},{"f":0,"t":0,"label":"Counter","kind":"note","cap":"Packets, a queue count, a license, a registration."},{"f":0,"t":0,"label":"Capture","kind":"ok","cap":"The ladder or the interval that shows the counter."}]},{"id":"study-path","title":"Study order","why":"SIP before products. Products before the platform you operate. Emergency and QoS before you call yourself done.","cite":"Campus study order","layout":"tree","actors":["Check"],"chart":"none","icon":"proof","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"SIP ladder","kind":"note","cap":"Read offer, answer, ACK, and BYE until you can draw them."},{"f":0,"t":0,"label":"CUCM and CUBE","kind":"note","cap":"CSS, route pattern, dial-peer, and the two Call-IDs."},{"f":0,"t":0,"label":"Your cloud","kind":"note","cap":"Webex Calling or Teams, then the contact center you run."},{"f":0,"t":0,"label":"Prove","kind":"ok","cap":"E911, QoS, and one troubleshooting drill with LICC."}]},{"id":"names-matter","title":"Use the product's names","why":"A bridge wastes time when two people use different words for the same object. Use the name in the admin guide.","cite":"Campus naming","layout":"tree","actors":["Check"],"chart":"none","icon":"cert","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Object","kind":"note","cap":"Route pattern, dial-peer, entry point, skill, or voice route. Pick the product's noun."},{"f":0,"t":0,"label":"Not a nickname","kind":"note","cap":"SBC is not always CUBE. Calling Plan is not Direct Routing."},{"f":0,"t":0,"label":"Version","kind":"note","cap":"Behavior changes between releases. Name the version you are looking at."},{"f":0,"t":0,"label":"Then debug","kind":"ok","cap":"Search the current document for that noun."}]},{"id":"call-path-map","title":"Call-path map","why":"Draw the signaling hops and the media hops as two lines. They are not the same line on a CUCM and CUBE call.","cite":"Campus map","layout":"tree","actors":["Check"],"chart":"none","icon":"route","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":true,"steps":[{"f":0,"t":0,"label":"Signaling","kind":"note","cap":"Phone, CUCM, CUBE, provider. Or client, cloud, SBC, provider."},{"f":0,"t":0,"label":"Media","kind":"media","cap":"Who is in RTP. CUCM is usually out. CUBE is usually in when it flow-through."},{"f":0,"t":0,"label":"Identifier","kind":"note","cap":"One id per signaling leg."},{"f":0,"t":0,"label":"Where you capture","kind":"ok","cap":"The hop you can actually span."}]},{"id":"call-path-full","title":"Full call-path map","why":"Add registration, emergency, and the reporting system beside the call. They fail independently.","cite":"Campus map","layout":"tree","actors":["Check"],"chart":"none","icon":"route","keys":[["LICC","Leg, id, counter, capture"],["One change","Then compare the same id"],["Call-ID","Join the logs"],["Current doc","Re-check before production"]],"header":null,"audio":false,"steps":[{"f":0,"t":0,"label":"Register","kind":"note","cap":"How the endpoint finds call control."},{"f":0,"t":0,"label":"Call","kind":"req","cap":"Signaling and media, drawn apart."},{"f":0,"t":0,"label":"Emergency","kind":"note","cap":"Location and on-site notification, not the normal route pattern."},{"f":0,"t":0,"label":"Report","kind":"note","cap":"CUIC, CTR, or the vendor call log. Beside the call, not inside RTP."}]},{"id":"campus-tour","title":"Campus tour","why":"Start with the ladder, then the border, then the cloud or the contact center you run. The visuals on each section are the same method: a picture, the numbers, and a step-through.","cite":"UC Lab","layout":"ladder","actors":["SIP","CUCM","CUBE","Cloud or CC"],"chart":"qos","icon":"proof","keys":[["476","Sections"],["14","Tracks"],["LICC","The habit"],["Offline","This file"]],"header":null,"audio":true,"steps":[{"f":0,"t":1,"label":"Dialog","kind":"req","cap":"Learn INVITE, 18x, 200, ACK, BYE, and where RTP actually flows."},{"f":1,"t":2,"label":"Border","kind":"note","cap":"CUCM chooses the route. CUBE starts a new dialog toward the carrier."},{"f":2,"t":3,"label":"Your platform","kind":"ok","cap":"Webex, Teams, UCCE, or the CCaaS you operate. The id changes. The legs do not."},{"f":3,"t":3,"label":"Proof","kind":"note","cap":"Emergency location and the QoS mark are part of done, not extras."}]}];
